INSERT INTO vocabularies (topic_id, word, phonetic, part_of_speech, meaning_vi, example_en, example_vi, audio_url, created_at, updated_at) VALUES ((SELECT id FROM topics WHERE name = 'Contracts' LIMIT 1), 'abide by', '/əˈbaɪd baɪ/', 'verb', 'tuân thủ, chấp hành', 'All employees are required to abide by the company safety regulations while on the job site.', 'Tất cả nhân viên được yêu cầu phải tuân thủ các quy định an toàn của công ty khi làm việc tại công trường.', '/uploads/audio/abide_by.wav', NOW(), NOW()) ON CONFLICT DO NOTHING;
INSERT INTO vocabularies (topic_id, word, phonetic, part_of_speech, meaning_vi, example_en, example_vi, audio_url, created_at, updated_at) VALUES ((SELECT id FROM topics WHERE name = 'Contracts' LIMIT 1), 'agreement', '/əˈɡriːmənt/', 'noun', 'bản thỏa thuận, hợp đồng', 'Both parties signed the final agreement after weeks of negotiations regarding the contract terms.', 'Cả hai bên đã ký bản thỏa thuận cuối cùng sau nhiều tuần đàm phán về các điều khoản hợp đồng.', '/uploads/audio/agreement.wav', NOW(), NOW()) ON CONFLICT DO NOTHING;
INSERT INTO vocabularies (topic_id, word, phonetic, part_of_speech, meaning_vi, example_en, example_vi, audio_url, created_at, updated_at) VALUES ((SELECT id FROM topics WHERE name = 'Contracts' LIMIT 1), 'assurance', '/əˈʃʊr.əns/', 'noun', 'sự đảm bảo, sự cam kết', 'The supplier gave us their full assurance that all materials would be delivered before the deadline.', 'Nhà cung cấp đã đưa ra sự đảm bảo hoàn toàn rằng tất cả nguyên vật liệu sẽ được giao trước thời hạn.', '/uploads/audio/assurance.wav', NOW(), NOW()) ON CONFLICT DO NOTHING;
INSERT INTO vocabularies (topic_id, word, phonetic, part_of_speech, meaning_vi, example_en, example_vi, audio_url, created_at, updated_at) VALUES ((SELECT id FROM topics WHERE name = 'Contracts' LIMIT 1), 'cancellation', '/ˌkæn.səlˈleɪ.ʃən/', 'noun', 'sự hủy bỏ', 'Due to unexpected scheduling conflicts, the board announced the cancellation of next week''s annual meeting.', 'Do xung đột lịch trình ngoài dự kiến, hội đồng quản trị đã thông báo hủy bỏ cuộc họp hàng năm vào tuần tới.', '/uploads/audio/cancellation.wav', NOW(), NOW()) ON CONFLICT DO NOTHING;
INSERT INTO vocabularies (topic_id, word, phonetic, part_of_speech, meaning_vi, example_en, example_vi, audio_url, created_at, updated_at) VALUES ((SELECT id FROM topics WHERE name = 'Contracts' LIMIT 1), 'determine', '/dɪˈtɜːrmɪn/', 'verb', 'xác định, quyết định', 'The committee will meet tomorrow to determine the final budget for the upcoming marketing campaign.', 'Ủy ban sẽ họp vào ngày mai để xác định ngân sách cuối cùng cho chiến dịch tiếp thị sắp tới.', '/uploads/audio/determine.wav', NOW(), NOW()) ON CONFLICT DO NOTHING;
INSERT INTO vocabularies (topic_id, word, phonetic, part_of_speech, meaning_vi, example_en, example_vi, audio_url, created_at, updated_at) VALUES ((SELECT id FROM topics WHERE name = 'Marketing' LIMIT 1), 'attract', '/əˈtrækt/', 'verb', 'thu hút', 'The new advertising campaign aims to attract potential customers to our recently launched line of eco-friendly products.', 'Chiến dịch quảng cáo mới nhằm mục đích thu hút khách hàng tiềm năng đến với dòng sản phẩm thân thiện với môi trường vừa ra mắt của chúng tôi.', '/uploads/audio/attract.wav', NOW(), NOW()) ON CONFLICT DO NOTHING;
INSERT INTO vocabularies (topic_id, word, phonetic, part_of_speech, meaning_vi, example_en, example_vi, audio_url, created_at, updated_at) VALUES ((SELECT id FROM topics WHERE name = 'Contracts' LIMIT 1), 'engage', '/ɪnˈɡeɪdʒ/', 'verb', 'thuê, ký hợp đồng dịch vụ', 'The company decided to engage a legal firm to review the terms of the new partnership contract.', 'Công ty đã quyết định thuê một công ty luật để xem xét các điều khoản của hợp đồng hợp tác mới.', '/uploads/audio/engage.wav', NOW(), NOW()) ON CONFLICT DO NOTHING;
INSERT INTO vocabularies (topic_id, word, phonetic, part_of_speech, meaning_vi, example_en, example_vi, audio_url, created_at, updated_at) VALUES ((SELECT id FROM topics WHERE name = 'Contracts' LIMIT 1), 'establish', '/ɪˈstæb.lɪʃ/', 'verb', 'thiết lập, quy định', 'Both parties agreed to establish clear guidelines regarding payment terms before signing the final service contract.', 'Cả hai bên đã đồng ý thiết lập các hướng dẫn rõ ràng về các điều khoản thanh toán trước khi ký hợp đồng dịch vụ chính thức.', '/uploads/audio/establish.wav', NOW(), NOW()) ON CONFLICT DO NOTHING;
INSERT INTO vocabularies (topic_id, word, phonetic, part_of_speech, meaning_vi, example_en, example_vi, audio_url, created_at, updated_at) VALUES ((SELECT id FROM topics WHERE name = 'Contracts' LIMIT 1), 'obligate', '/ˈɑː.blə.ɡeɪt/', 'verb', 'bắt buộc, ràng buộc', 'The signed contract will obligate both parties to fulfill their agreed duties within the specified timeframe.', 'Hợp đồng đã ký sẽ bắt buộc cả hai bên phải hoàn thành các nhiệm vụ đã thỏa thuận trong khoảng thời gian quy định.', '/uploads/audio/obligate.wav', NOW(), NOW()) ON CONFLICT DO NOTHING;
INSERT INTO vocabularies (topic_id, word, phonetic, part_of_speech, meaning_vi, example_en, example_vi, audio_url, created_at, updated_at) VALUES ((SELECT id FROM topics WHERE name = 'Contracts' LIMIT 1), 'party', '/ˈpɑːr.t̬i/', 'noun', 'bên (trong hợp đồng, giao kèo)', 'Both parties must sign the non-disclosure agreement before any confidential business information can be shared.', 'Cả hai bên phải ký thỏa thuận bảo mật trước khi bất kỳ thông tin kinh doanh mật nào được chia sẻ.', '/uploads/audio/party.wav', NOW(), NOW()) ON CONFLICT DO NOTHING;
INSERT INTO vocabularies (topic_id, word, phonetic, part_of_speech, meaning_vi, example_en, example_vi, audio_url, created_at, updated_at) VALUES ((SELECT id FROM topics WHERE name = 'Contracts' LIMIT 1), 'provision', '/prəˈvɪʒ.ən/', 'noun', 'điều khoản (hợp đồng)', 'The new contract contains a specific provision that protects the company against unexpected price increases.', 'Hợp đồng mới có một điều khoản cụ thể nhằm bảo vệ công ty trước việc tăng giá bất ngờ.', '/uploads/audio/provision.wav', NOW(), NOW()) ON CONFLICT DO NOTHING;
INSERT INTO vocabularies (topic_id, word, phonetic, part_of_speech, meaning_vi, example_en, example_vi, audio_url, created_at, updated_at) VALUES ((SELECT id FROM topics WHERE name = 'Contracts' LIMIT 1), 'resolve', '/rɪˈzɑːlv/', 'verb', 'giải quyết (tranh chấp, mâu thuẫn)', 'Both parties agreed to resolve the contract dispute through mediation before initiating any legal proceedings.', 'Cả hai bên đã đồng ý giải quyết tranh chấp hợp đồng thông qua hòa giải trước khi khởi kiện.', '/uploads/audio/resolve.wav', NOW(), NOW()) ON CONFLICT DO NOTHING;
INSERT INTO vocabularies (topic_id, word, phonetic, part_of_speech, meaning_vi, example_en, example_vi, audio_url, created_at, updated_at) VALUES ((SELECT id FROM topics WHERE name = 'Contracts' LIMIT 1), 'specific', '/spəˈsɪf.ɪk/', 'adjective', 'cụ thể, rõ ràng', 'The contract outlines specific terms regarding payment schedules and delivery deadlines for all involved parties.', 'Hợp đồng nêu rõ các điều khoản cụ thể liên quan đến lịch trình thanh toán và thời hạn giao hàng cho tất cả các bên liên quan.', '/uploads/audio/specific.wav', NOW(), NOW()) ON CONFLICT DO NOTHING;
INSERT INTO vocabularies (topic_id, word, phonetic, part_of_speech, meaning_vi, example_en, example_vi, audio_url, created_at, updated_at) VALUES ((SELECT id FROM topics WHERE name = 'Contracts' LIMIT 1), 'breach', '/briːtʃ/', 'noun', 'sự vi phạm, sự phá vỡ (hợp đồng)', 'Failing to deliver the equipment on the agreed date will be considered a serious breach of the contract.', 'Việc không giao thiết bị đúng ngày đã thỏa thuận sẽ được coi là sự vi phạm hợp đồng nghiêm trọng.', '/uploads/audio/breach.wav', NOW(), NOW()) ON CONFLICT DO NOTHING;
INSERT INTO vocabularies (topic_id, word, phonetic, part_of_speech, meaning_vi, example_en, example_vi, audio_url, created_at, updated_at) VALUES ((SELECT id FROM topics WHERE name = 'Contracts' LIMIT 1), 'settlement', '/ˈset̬.əl.mənt/', 'noun', 'thỏa thuận dàn xếp, sự giải quyết tranh chấp', 'Both companies reached a financial settlement to resolve the contract dispute without going to court.', 'Cả hai công ty đã đạt được một thỏa thuận tài chính để giải quyết tranh chấp hợp đồng mà không phải ra tòa.', '/uploads/audio/settlement.wav', NOW(), NOW()) ON CONFLICT DO NOTHING;
INSERT INTO vocabularies (topic_id, word, phonetic, part_of_speech, meaning_vi, example_en, example_vi, audio_url, created_at, updated_at) VALUES ((SELECT id FROM topics WHERE name = 'Customer Service' LIMIT 1), 'policy', '/ˈpɑː.lə.si/', 'noun', 'chính sách, quy định', 'According to our company''s return policy, customers can receive a full refund within thirty days of purchase.', 'Theo chính sách trả hàng của công ty chúng tôi, khách hàng có thể nhận lại toàn bộ tiền trong vòng ba mươi ngày kể từ khi mua.', '/uploads/audio/policy.wav', NOW(), NOW()) ON CONFLICT DO NOTHING;
INSERT INTO vocabularies (topic_id, word, phonetic, part_of_speech, meaning_vi, example_en, example_vi, audio_url, created_at, updated_at) VALUES ((SELECT id FROM topics WHERE name = 'Contracts' LIMIT 1), 'clause', '/klɔːz/', 'noun', 'điều khoản (trong hợp đồng)', 'The legal department added a confidentiality clause to the contract to protect proprietary company information.', 'Bộ phận pháp chế đã thêm một điều khoản bảo mật vào hợp đồng để bảo vệ thông tin độc quyền của công ty.', '/uploads/audio/clause.wav', NOW(), NOW()) ON CONFLICT DO NOTHING;
INSERT INTO vocabularies (topic_id, word, phonetic, part_of_speech, meaning_vi, example_en, example_vi, audio_url, created_at, updated_at) VALUES ((SELECT id FROM topics WHERE name = 'Contracts' LIMIT 1), 'negotiate', '/nɪˈɡoʊ.ʃi.eɪt/', 'verb', 'đàm phán, thương lượng', 'The legal team is working hard to negotiate the terms of the new contract before the end of the month.', 'Đội ngũ pháp lý đang nỗ lực làm việc để đàm phán các điều khoản của hợp đồng mới trước cuối tháng.', '/uploads/audio/negotiate.wav', NOW(), NOW()) ON CONFLICT DO NOTHING;
INSERT INTO vocabularies (topic_id, word, phonetic, part_of_speech, meaning_vi, example_en, example_vi, audio_url, created_at, updated_at) VALUES ((SELECT id FROM topics WHERE name = 'Contracts' LIMIT 1), 'binding', '/ˈbaɪn.dɪŋ/', 'adjective', 'córàngbuộc,cóhiệulựcthipháp', 'Both parties must sign the agreement before it becomes legally binding next week.', 'Cả hai bên phải ký vào thỏa thuận trước khi nó có hiệu lực pháp lý vào tuần tới.', '/uploads/audio/binding.wav', NOW(), NOW()) ON CONFLICT DO NOTHING;
INSERT INTO vocabularies (topic_id, word, phonetic, part_of_speech, meaning_vi, example_en, example_vi, audio_url, created_at, updated_at) VALUES ((SELECT id FROM topics WHERE name = 'Contracts' LIMIT 1), 'stipulate', '/ˈstɪp.jə.leɪt/', 'verb', 'quy định, đặt điều kiện', 'The contract stipulates that the service provider must deliver the monthly reports by the first business day of each month.', 'Hợp đồng quy định rằng nhà cung cấp dịch vụ phải gửi các báo cáo hàng tháng trước ngày làm việc đầu tiên của mỗi tháng.', '/uploads/audio/stipulate.wav', NOW(), NOW()) ON CONFLICT DO NOTHING;
INSERT INTO vocabularies (topic_id, word, phonetic, part_of_speech, meaning_vi, example_en, example_vi, audio_url, created_at, updated_at) VALUES ((SELECT id FROM topics WHERE name = 'Contracts' LIMIT 1), 'liability', '/ˌlaɪ.əˈbɪl.ə.t̬i/', 'noun', 'trách nhiệm pháp lý, khoản nợ', 'The new contract limits the company''s legal liability in case of unexpected project delays.', 'Hợp đồng mới giới hạn trách nhiệm pháp lý của công ty trong trường hợp dự án bị chậm trễ bất ngờ.', '/uploads/audio/liability.wav', NOW(), NOW()) ON CONFLICT DO NOTHING;
INSERT INTO vocabularies (topic_id, word, phonetic, part_of_speech, meaning_vi, example_en, example_vi, audio_url, created_at, updated_at) VALUES ((SELECT id FROM topics WHERE name = 'Contracts' LIMIT 1), 'terminate', '/ˈtɜːr.mɪ.neɪt/', 'verb', 'chấm dứt, hủy bỏ (hợp đồng)', 'Either party may terminate the contract by giving thirty days'' written notice to the other party.', 'Bất kỳ bên nào cũng có thể chấm dứt hợp đồng bằng cách gửi thông báo bằng văn bản trước ba mươi ngày cho bên kia.', '/uploads/audio/terminate.wav', NOW(), NOW()) ON CONFLICT DO NOTHING;
INSERT INTO vocabularies (topic_id, word, phonetic, part_of_speech, meaning_vi, example_en, example_vi, audio_url, created_at, updated_at) VALUES ((SELECT id FROM topics WHERE name = 'Contracts' LIMIT 1), 'amendment', '/əˈmen.dmənt/', 'noun', 'sửa đổi, bổ sung (hợp đồng, điều luật)', 'Both parties must sign and date every amendment made to the original service contract.', 'Cả hai bên phải ký tên và ghi ngày vào mọi sửa đổi được thực hiện đối với hợp đồng dịch vụ ban đầu.', '/uploads/audio/amendment.wav', NOW(), NOW()) ON CONFLICT DO NOTHING;
INSERT INTO vocabularies (topic_id, word, phonetic, part_of_speech, meaning_vi, example_en, example_vi, audio_url, created_at, updated_at) VALUES ((SELECT id FROM topics WHERE name = 'Contracts' LIMIT 1), 'comply with', '/kəmˈplaɪ wɪð/', 'phrasal verb', 'tuân thủ, tuân theo (điều khoản, quy định)', 'Both parties must strictly comply with all the terms and conditions outlined in the signed agreement.', 'Cả hai bên phải tuân thủ nghiêm ngặt mọi điều khoản và điều kiện được nêu trong thỏa thuận đã ký.', '/uploads/audio/comply_with.wav', NOW(), NOW()) ON CONFLICT DO NOTHING;
INSERT INTO vocabularies (topic_id, word, phonetic, part_of_speech, meaning_vi, example_en, example_vi, audio_url, created_at, updated_at) VALUES ((SELECT id FROM topics WHERE name = 'Contracts' LIMIT 1), 'enforce', '/ɪnˈfɔːrs/', 'verb', 'thực thi, thi hành (điều khoản, hợp đồng)', 'The legal department will enforce the non-disclosure agreement if any confidential company information is leaked to the public.', 'Bộ phận pháp lý sẽ thực thi thỏa thuận bảo mật thông tin nếu có bất kỳ thông tin bí mật nào của công ty bị rò rỉ ra công chúng.', '/uploads/audio/enforce.wav', NOW(), NOW()) ON CONFLICT DO NOTHING;
INSERT INTO vocabularies (topic_id, word, phonetic, part_of_speech, meaning_vi, example_en, example_vi, audio_url, created_at, updated_at) VALUES ((SELECT id FROM topics WHERE name = 'Contracts' LIMIT 1), 'consent', '/kənˈsɛnt/', 'noun', 'sự đồng ý, sự cho phép', 'Neither party may assign this agreement without the prior written consent of the other.', 'Không bên nào được chuyển nhượng thỏa thuận này nếu không có sự đồng ý trước bằng văn bản của bên kia.', '/uploads/audio/consent.wav', NOW(), NOW()) ON CONFLICT DO NOTHING;
INSERT INTO vocabularies (topic_id, word, phonetic, part_of_speech, meaning_vi, example_en, example_vi, audio_url, created_at, updated_at) VALUES ((SELECT id FROM topics WHERE name = 'Contracts' LIMIT 1), 'dispute', '/dɪˈspjuːt/', 'noun', 'cuộc tranh chấp, sự bất đồng', 'The contract contains a specific clause outlining how any payment dispute between the two parties will be resolved.', 'Hợp đồng bao gồm một điều khoản cụ thể nêu rõ cách giải quyết bất kỳ tranh chấp thanh toán nào giữa hai bên.', '/uploads/audio/dispute.wav', NOW(), NOW()) ON CONFLICT DO NOTHING;
INSERT INTO vocabularies (topic_id, word, phonetic, part_of_speech, meaning_vi, example_en, example_vi, audio_url, created_at, updated_at) VALUES ((SELECT id FROM topics WHERE name = 'Contracts' LIMIT 1), 'null and void', '/nʌl ənd vɔɪd/', 'adjective', 'vô hiệu lực, không còn giá trị pháp lý', 'The service agreement will be considered null and void if both parties fail to sign it.', 'Thỏa thuận dịch vụ sẽ bị coi là vô hiệu lực nếu cả hai bên không ký kết nó.', '/uploads/audio/null_and_void.wav', NOW(), NOW()) ON CONFLICT DO NOTHING;
INSERT INTO vocabularies (topic_id, word, phonetic, part_of_speech, meaning_vi, example_en, example_vi, audio_url, created_at, updated_at) VALUES ((SELECT id FROM topics WHERE name = 'Contracts' LIMIT 1), 'term', '/tɜːrm/', 'noun', 'thời hạn, điều khoản (hợp đồng)', 'The term of the lease agreement is one year, with an option to renew for another twelve months.', 'Thời hạn của hợp đồng thuê nhà là một năm, với tùy chọn gia hạn thêm mười hai tháng nữa.', '/uploads/audio/term.wav', NOW(), NOW()) ON CONFLICT DO NOTHING;
INSERT INTO vocabularies (topic_id, word, phonetic, part_of_speech, meaning_vi, example_en, example_vi, audio_url, created_at, updated_at) VALUES ((SELECT id FROM topics WHERE name = 'Contracts' LIMIT 1), 'validity', '/vəˈlɪd.ə.t̬i/', 'noun', 'hiệu lực, giá trị pháp lý', 'Both parties must sign the new agreement to ensure its legal validity.', 'Cả hai bên phải ký vào thỏa thuận mới để đảm bảo hiệu lực pháp lý của nó.', '/uploads/audio/validity.wav', NOW(), NOW()) ON CONFLICT DO NOTHING;
INSERT INTO vocabularies (topic_id, word, phonetic, part_of_speech, meaning_vi, example_en, example_vi, audio_url, created_at, updated_at) VALUES ((SELECT id FROM topics WHERE name = 'Contracts' LIMIT 1), 'fulfill', '/fʊlˈfɪl/', 'verb', 'hoàn thành, thực hiện (nghĩa vụ, hợp đồng), đáp ứng', 'The supplier failed to fulfill the terms of the contract, resulting in a delay of the shipment.', 'Nhà cung cấp đã không thực hiện đúng các điều khoản của hợp đồng, dẫn đến việc chậm trễ giao hàng.', '/uploads/audio/fulfill.wav', NOW(), NOW()) ON CONFLICT DO NOTHING;
INSERT INTO vocabularies (topic_id, word, phonetic, part_of_speech, meaning_vi, example_en, example_vi, audio_url, created_at, updated_at) VALUES ((SELECT id FROM topics WHERE name = 'Contracts' LIMIT 1), 'guarantee', '/ˌɡer.ənˈtiː/', 'verb', 'bảo đảm, cam kết', 'The supplier refused to sign the contract unless we could guarantee payment within thirty days.', 'Nhà cung cấp đã từ chối ký hợp đồng trừ khi chúng tôi có thể bảo đảm thanh toán trong vòng ba mươi ngày.', '/uploads/audio/guarantee.wav', NOW(), NOW()) ON CONFLICT DO NOTHING;
INSERT INTO vocabularies (topic_id, word, phonetic, part_of_speech, meaning_vi, example_en, example_vi, audio_url, created_at, updated_at) VALUES ((SELECT id FROM topics WHERE name = 'Customer Service' LIMIT 1), 'complaint', '/kəmˈpleɪnt/', 'noun', 'sự khiếu nại, lời phàn nàn', 'Our customer service team resolved the complaint regarding the delayed shipment within twenty-four hours.', 'Đội ngũ dịch vụ khách hàng của chúng tôi đã giải quyết khiếu nại liên quan đến việc giao hàng trễ trong vòng 24 giờ.', '/uploads/audio/complaint.wav', NOW(), NOW()) ON CONFLICT DO NOTHING;
INSERT INTO vocabularies (topic_id, word, phonetic, part_of_speech, meaning_vi, example_en, example_vi, audio_url, created_at, updated_at) VALUES ((SELECT id FROM topics WHERE name = 'Customer Service' LIMIT 1), 'inquiry', '/ɪnˈkwɪri/', 'noun', 'câu hỏi, sự yêu cầu thông tin', 'Our customer service team handles every client inquiry promptly and professionally to ensure satisfaction.', 'Đội ngũ chăm sóc khách hàng của chúng tôi giải quyết mọi thắc mắc của khách hàng một cách nhanh chóng và chuyên nghiệp để đảm bảo sự hài lòng.', '/uploads/audio/inquiry.wav', NOW(), NOW()) ON CONFLICT DO NOTHING;
INSERT INTO vocabularies (topic_id, word, phonetic, part_of_speech, meaning_vi, example_en, example_vi, audio_url, created_at, updated_at) VALUES ((SELECT id FROM topics WHERE name = 'Customer Service' LIMIT 1), 'feedback', '/ˈfiːd.bæk/', 'noun', 'ý kiến phản hồi, sự phản hồi', 'We highly value customer feedback and use it to improve the quality of our services and products.', 'Chúng tôi đánh giá cao ý kiến phản hồi của khách hàng và sử dụng nó để nâng cao chất lượng dịch vụ và sản phẩm của mình.', '/uploads/audio/feedback.wav', NOW(), NOW()) ON CONFLICT DO NOTHING;
INSERT INTO vocabularies (topic_id, word, phonetic, part_of_speech, meaning_vi, example_en, example_vi, audio_url, created_at, updated_at) VALUES ((SELECT id FROM topics WHERE name = 'Customer Service' LIMIT 1), 'satisfaction', '/ˌsætɪsˈfækʃn/', 'noun', 'sự hài lòng', 'Ensuring customer satisfaction is our top priority for all representatives in this department.', 'Đảm bảo sự hài lòng của khách hàng là ưu tiên hàng đầu của chúng tôi đối với tất cả đại diện trong phòng này.', '/uploads/audio/satisfaction.wav', NOW(), NOW()) ON CONFLICT DO NOTHING;
INSERT INTO vocabularies (topic_id, word, phonetic, part_of_speech, meaning_vi, example_en, example_vi, audio_url, created_at, updated_at) VALUES ((SELECT id FROM topics WHERE name = 'Customer Service' LIMIT 1), 'representative', '/ˌreprɪˈzentətɪv/', 'noun', 'người đại diện, nhân viên đại diện', 'If you experience any issues with your order, please contact a customer service representative immediately for assistance.', 'Nếu bạn gặp bất kỳ vấn đề nào với đơn hàng của mình, vui lòng liên hệ ngay với đại diện dịch vụ khách hàng để được hỗ trợ.', '/uploads/audio/representative.wav', NOW(), NOW()) ON CONFLICT DO NOTHING;
INSERT INTO vocabularies (topic_id, word, phonetic, part_of_speech, meaning_vi, example_en, example_vi, audio_url, created_at, updated_at) VALUES ((SELECT id FROM topics WHERE name = 'Customer Service' LIMIT 1), 'assistance', '/əˈsɪs.təns/', 'noun', 'sự hỗ trợ, sự giúp đỡ', 'Please contact our customer service hotline if you need further assistance with your online order.', 'Vui lòng liên hệ với đường dây nóng dịch vụ khách hàng của chúng tôi nếu bạn cần hỗ trợ thêm về đơn hàng trực tuyến.', '/uploads/audio/assistance.wav', NOW(), NOW()) ON CONFLICT DO NOTHING;
INSERT INTO vocabularies (topic_id, word, phonetic, part_of_speech, meaning_vi, example_en, example_vi, audio_url, created_at, updated_at) VALUES ((SELECT id FROM topics WHERE name = 'Customer Service' LIMIT 1), 'apologize', '/əˈpɑː.lə.dʒaɪz/', 'verb', 'xin lỗi', 'We sincerely apologize for the shipping delay and would like to offer you a discount on your next purchase.', 'Chúng tôi chân thành xin lỗi vì sự chậm trễ giao hàng và muốn gửi tặng bạn một mã giảm giá cho lần mua hàng tiếp theo.', '/uploads/audio/apologize.wav', NOW(), NOW()) ON CONFLICT DO NOTHING;
INSERT INTO vocabularies (topic_id, word, phonetic, part_of_speech, meaning_vi, example_en, example_vi, audio_url, created_at, updated_at) VALUES ((SELECT id FROM topics WHERE name = 'Customer Service' LIMIT 1), 'courteous', '/ˈkɝː.t̬i.əs/', 'adjective', 'lịch sự, nhã nhặn', 'Customer service representatives must remain courteous and professional even when dealing with difficult clients.', 'Nhân viên chăm sóc khách hàng phải luôn lịch sự và chuyên nghiệp ngay cả khi đối phó với những khách hàng khó tính.', '/uploads/audio/courteous.wav', NOW(), NOW()) ON CONFLICT DO NOTHING;
INSERT INTO vocabularies (topic_id, word, phonetic, part_of_speech, meaning_vi, example_en, example_vi, audio_url, created_at, updated_at) VALUES ((SELECT id FROM topics WHERE name = 'Customer Service' LIMIT 1), 'prompt', '/prɑːmpt/', 'adjective', 'nhanh chóng, kịp thời', 'Our customer support team is committed to providing prompt replies to all inquiries received through our online portal.', 'Đội ngũ hỗ trợ khách hàng của chúng tôi cam kết cung cấp phản hồi nhanh chóng cho tất cả các thắc mắc nhận được qua cổng trực tuyến.', '/uploads/audio/prompt.wav', NOW(), NOW()) ON CONFLICT DO NOTHING;
INSERT INTO vocabularies (topic_id, word, phonetic, part_of_speech, meaning_vi, example_en, example_vi, audio_url, created_at, updated_at) VALUES ((SELECT id FROM topics WHERE name = 'Customer Service' LIMIT 1), 'resolution', '/ˌrɛz.əˈluː.ʃən/', 'noun', 'sự giải quyết, phương án giải quyết (khiếu nại, vấn đề)', 'Our customer support team is dedicated to ensuring the quick resolution of all client complaints.', 'Đội ngũ hỗ trợ khách hàng của chúng tôi tận tâm đảm bảo việc giải quyết nhanh chóng mọi khiếu nại của khách hàng.', '/uploads/audio/resolution.wav', NOW(), NOW()) ON CONFLICT DO NOTHING;
INSERT INTO vocabularies (topic_id, word, phonetic, part_of_speech, meaning_vi, example_en, example_vi, audio_url, created_at, updated_at) VALUES ((SELECT id FROM topics WHERE name = 'Customer Service' LIMIT 1), 'compensation', '/ˌkɑːm.pənˈseɪ.ʃən/', 'noun', 'sự bồi thường, tiền đền bù', 'The airline offered travel vouchers as compensation to passengers whose flights were delayed for over four hours.', 'Hãng hàng không đã đề xuất các phiếu giảm giá du lịch như một khoản bồi thường cho những hành khách có chuyến bay bị hoãn hơn bốn giờ.', '/uploads/audio/compensation.wav', NOW(), NOW()) ON CONFLICT DO NOTHING;
INSERT INTO vocabularies (topic_id, word, phonetic, part_of_speech, meaning_vi, example_en, example_vi, audio_url, created_at, updated_at) VALUES ((SELECT id FROM topics WHERE name = 'Customer Service' LIMIT 1), 'hotline', '/ˈhɑːt.laɪn/', 'noun', 'đường dây nóng (hỗ trợ khách hàng)', 'Customers can reach our support team 24 hours a day through the toll-free hotline.', 'Khách hàng có thể liên hệ với đội ngũ hỗ trợ của chúng tôi 24 giờ một ngày qua đường dây nóng miễn phí.', '/uploads/audio/hotline.wav', NOW(), NOW()) ON CONFLICT DO NOTHING;
INSERT INTO vocabularies (topic_id, word, phonetic, part_of_speech, meaning_vi, example_en, example_vi, audio_url, created_at, updated_at) VALUES ((SELECT id FROM topics WHERE name = 'Customer Service' LIMIT 1), 'support', '/səˈpɔːrt/', 'noun', 'sự hỗ trợ, dịch vụ hỗ trợ', 'Our dedicated customer support team is available around the clock to resolve any technical issues you may encounter.', 'Đội ngũ hỗ trợ khách hàng tận tụy của chúng tôi sẵn sàng phục vụ suốt ngày đêm để giải quyết mọi sự cố kỹ thuật mà bạn có thể gặp phải.', '/uploads/audio/support.wav', NOW(), NOW()) ON CONFLICT DO NOTHING;
INSERT INTO vocabularies (topic_id, word, phonetic, part_of_speech, meaning_vi, example_en, example_vi, audio_url, created_at, updated_at) VALUES ((SELECT id FROM topics WHERE name = 'Customer Service' LIMIT 1), 'clarification', '/ˌklɛr.ə.fəˈkeɪ.ʃən/', 'noun', 'sự làm rõ, sự giải thích thêm', 'Please contact our customer support hotline if you need any further clarification on your billing statement.', 'Vui lòng liên hệ với đường dây nóng hỗ trợ khách hàng của chúng tôi nếu bạn cần giải thích thêm về bảng sao kê thanh toán.', '/uploads/audio/clarification.wav', NOW(), NOW()) ON CONFLICT DO NOTHING;
INSERT INTO vocabularies (topic_id, word, phonetic, part_of_speech, meaning_vi, example_en, example_vi, audio_url, created_at, updated_at) VALUES ((SELECT id FROM topics WHERE name = 'Customer Service' LIMIT 1), 'follow up', '/ˈfɑːl.oʊ ʌp/', 'phrasal verb', 'liên hệ lại, theo dõi kết quả (để tiếp tục giải quyết công việc)', 'Our support team will follow up with you tomorrow to ensure that your technical issue has been completely resolved.', 'Đội ngũ hỗ trợ của chúng tôi sẽ liên hệ lại với bạn vào ngày mai để đảm bảo rằng sự cố kỹ thuật của bạn đã được giải quyết hoàn toàn.', '/uploads/audio/follow_up.wav', NOW(), NOW()) ON CONFLICT DO NOTHING;
INSERT INTO vocabularies (topic_id, word, phonetic, part_of_speech, meaning_vi, example_en, example_vi, audio_url, created_at, updated_at) VALUES ((SELECT id FROM topics WHERE name = 'Customer Service' LIMIT 1), 'escort', '/ˈɛsˌkɔrt/', 'verb', 'hộ tống, dẫn đường, đi kèm', 'A customer service representative will escort you to the VIP lounge upon arrival.', 'Một nhân viên dịch vụ khách hàng sẽ hộ tống bạn đến phòng chờ VIP khi bạn đến nơi.', '/uploads/audio/escort.wav', NOW(), NOW()) ON CONFLICT DO NOTHING;
INSERT INTO vocabularies (topic_id, word, phonetic, part_of_speech, meaning_vi, example_en, example_vi, audio_url, created_at, updated_at) VALUES ((SELECT id FROM topics WHERE name = 'Customer Service' LIMIT 1), 'loyalty', '/ˈlɔɪ.əl.ti/', 'noun', 'lòng trung thành, sự trung thành', 'Our new rewards program is designed to foster customer loyalty by offering exclusive discounts and personalized promotions.', 'Chương trình phần thưởng mới của chúng tôi được thiết kế để thúc đẩy lòng trung thành của khách hàng bằng cách cung cấp các khoản giảm giá độc quyền và khuyến mãi cá nhân hóa.', '/uploads/audio/loyalty.wav', NOW(), NOW()) ON CONFLICT DO NOTHING;
INSERT INTO vocabularies (topic_id, word, phonetic, part_of_speech, meaning_vi, example_en, example_vi, audio_url, created_at, updated_at) VALUES ((SELECT id FROM topics WHERE name = 'Customer Service' LIMIT 1), 'patron', '/ˈpeɪ.trən/', 'noun', 'khách hàng quen, khách hàng thường xuyên', 'Our restaurant offers a complimentary dessert to every loyal patron during their birthday month.', 'Nhà hàng của chúng tôi phục vụ món tráng miệng miễn phí cho mọi khách hàng thân thiết trong tháng sinh nhật của họ.', '/uploads/audio/patron.wav', NOW(), NOW()) ON CONFLICT DO NOTHING;
INSERT INTO vocabularies (topic_id, word, phonetic, part_of_speech, meaning_vi, example_en, example_vi, audio_url, created_at, updated_at) VALUES ((SELECT id FROM topics WHERE name = 'Customer Service' LIMIT 1), 'client', '/ˈklaɪ.ənt/', 'noun', 'khách hàng, đối tác', 'Our customer service representatives are trained to resolve any issues quickly to ensure that every client remains satisfied.', 'Các đại diện dịch vụ khách hàng của chúng tôi được đào tạo để giải quyết mọi vấn đề nhanh chóng nhằm đảm bảo mọi khách hàng đều hài lòng.', '/uploads/audio/client.wav', NOW(), NOW()) ON CONFLICT DO NOTHING;
INSERT INTO vocabularies (topic_id, word, phonetic, part_of_speech, meaning_vi, example_en, example_vi, audio_url, created_at, updated_at) VALUES ((SELECT id FROM topics WHERE name = 'Customer Service' LIMIT 1), 'consultation', '/ˌkɑːn.səlˈteɪ.ʃən/', 'noun', 'sự tư vấn, buổi tham khảo ý kiến', 'Please schedule a free consultation with our customer support team to discuss your account options.', 'Vui lòng đặt lịch hẹn tư vấn miễn phí với đội ngũ hỗ trợ khách hàng của chúng tôi để thảo luận về các tùy chọn tài khoản của bạn.', '/uploads/audio/consultation.wav', NOW(), NOW()) ON CONFLICT DO NOTHING;
INSERT INTO vocabularies (topic_id, word, phonetic, part_of_speech, meaning_vi, example_en, example_vi, audio_url, created_at, updated_at) VALUES ((SELECT id FROM topics WHERE name = 'Customer Service' LIMIT 1), 'survey', '/ˈsɝː.veɪ/', 'noun', 'khảo sát ý kiến', 'Please complete our online customer service survey to help us improve your shopping experience.', 'Vui lòng hoàn thành khảo sát dịch vụ khách hàng trực tuyến của chúng tôi để giúp chúng tôi cải thiện trải nghiệm mua sắm của bạn.', '/uploads/audio/survey.wav', NOW(), NOW()) ON CONFLICT DO NOTHING;
INSERT INTO vocabularies (topic_id, word, phonetic, part_of_speech, meaning_vi, example_en, example_vi, audio_url, created_at, updated_at) VALUES ((SELECT id FROM topics WHERE name = 'Customer Service' LIMIT 1), 'reputation', '/ˌrep.jəˈteɪ.ʃən/', 'noun', 'danh tiếng, uy tín', 'Our company has built a strong reputation for delivering exceptional customer service over the years.', 'Công ty chúng tôi đã xây dựng được một uy tín vững chắc về việc cung cấp dịch vụ khách hàng xuất sắc trong nhiều năm qua.', '/uploads/audio/reputation.wav', NOW(), NOW()) ON CONFLICT DO NOTHING;
INSERT INTO vocabularies (topic_id, word, phonetic, part_of_speech, meaning_vi, example_en, example_vi, audio_url, created_at, updated_at) VALUES ((SELECT id FROM topics WHERE name = 'Customer Service' LIMIT 1), 'testimonial', '/ˌtes.təˈmoʊ.ni.əl/', 'noun', 'lời chứng thực, đánh giá của khách hàng', 'We received a positive customer testimonial regarding the prompt support provided by our technical team.', 'Chúng tôi đã nhận được một lời đánh giá tích cực từ khách hàng về sự hỗ trợ nhanh chóng từ đội ngũ kỹ thuật.', '/uploads/audio/testimonial.wav', NOW(), NOW()) ON CONFLICT DO NOTHING;
INSERT INTO vocabularies (topic_id, word, phonetic, part_of_speech, meaning_vi, example_en, example_vi, audio_url, created_at, updated_at) VALUES ((SELECT id FROM topics WHERE name = 'Customer Service' LIMIT 1), 'standard', '/ˈstæn.dɚd/', 'noun', 'tiêu chuẩn, mức chuẩn', 'Our support team is committed to maintaining high standards of customer service at all times.', 'Đội ngũ hỗ trợ của chúng tôi cam kết luôn duy trì các tiêu chuẩn dịch vụ khách hàng cao.', '/uploads/audio/standard.wav', NOW(), NOW()) ON CONFLICT DO NOTHING;
INSERT INTO vocabularies (topic_id, word, phonetic, part_of_speech, meaning_vi, example_en, example_vi, audio_url, created_at, updated_at) VALUES ((SELECT id FROM topics WHERE name = 'Customer Service' LIMIT 1), 'expectation', '/ˌek.spekˈteɪ.ʃən/', 'noun', 'sự kỳ vọng, mong đợi', 'Our support team always strives to exceed customer expectations by resolving complaints quickly.', 'Đội ngũ hỗ trợ của chúng tôi luôn nỗ lực vượt qua kỳ vọng của khách hàng bằng cách giải quyết khiếu nại nhanh chóng.', '/uploads/audio/expectation.wav', NOW(), NOW()) ON CONFLICT DO NOTHING;
INSERT INTO vocabularies (topic_id, word, phonetic, part_of_speech, meaning_vi, example_en, example_vi, audio_url, created_at, updated_at) VALUES ((SELECT id FROM topics WHERE name = 'Customer Service' LIMIT 1), 'courtesy', '/ˈkɜːr.t̬ə.si/', 'noun', 'sự lịch thiệp, phép lịch sự', 'Our representatives are trained to treat every customer with the utmost courtesy and respect during service calls.', 'Các đại diện của chúng tôi được đào tạo để đối xử với mọi khách hàng bằng sự lịch thiệp và tôn trọng tối đa trong các cuộc gọi dịch vụ.', '/uploads/audio/courtesy.wav', NOW(), NOW()) ON CONFLICT DO NOTHING;
INSERT INTO vocabularies (topic_id, word, phonetic, part_of_speech, meaning_vi, example_en, example_vi, audio_url, created_at, updated_at) VALUES ((SELECT id FROM topics WHERE name = 'Customer Service' LIMIT 1), 'efficiency', '/ɪˈfɪʃ.ən.si/', 'noun', 'hiệu suất, hiệu quả', 'Our support team upgraded the software to improve customer service efficiency and response times.', 'Nhóm hỗ trợ của chúng tôi đã nâng cao phần mềm để cải thiện hiệu quả dịch vụ khách hàng và thời gian phản hồi.', '/uploads/audio/efficiency.wav', NOW(), NOW()) ON CONFLICT DO NOTHING;
INSERT INTO vocabularies (topic_id, word, phonetic, part_of_speech, meaning_vi, example_en, example_vi, audio_url, created_at, updated_at) VALUES ((SELECT id FROM topics WHERE name = 'Finance' LIMIT 1), 'revenue', '/ˈrɛv.ə.nuː/', 'noun', 'doanh thu', 'The company reported a significant increase in quarterly revenue due to strong international sales.', 'Công ty đã báo cáo sự gia tăng đáng kể về doanh thu hàng quý do doanh số bán hàng quốc tế mạnh mẽ.', '/uploads/audio/revenue.wav', NOW(), NOW()) ON CONFLICT DO NOTHING;
INSERT INTO vocabularies (topic_id, word, phonetic, part_of_speech, meaning_vi, example_en, example_vi, audio_url, created_at, updated_at) VALUES ((SELECT id FROM topics WHERE name = 'Finance' LIMIT 1), 'expenditure', '/ɪkˈspen.də.tʃɚ/', 'noun', 'khoản chi tiêu, chi phí', 'The finance department is reviewing the annual advertising expenditure to reduce unnecessary company costs.', 'Phòng tài chính đang xem xét khoản chi tiêu quảng cáo hàng năm để cắt giảm các chi phí không cần thiết của công ty.', '/uploads/audio/expenditure.wav', NOW(), NOW()) ON CONFLICT DO NOTHING;
INSERT INTO vocabularies (topic_id, word, phonetic, part_of_speech, meaning_vi, example_en, example_vi, audio_url, created_at, updated_at) VALUES ((SELECT id FROM topics WHERE name = 'Finance' LIMIT 1), 'budget', '/ˈbʌdʒ.ɪt/', 'noun', 'ngân sách', 'The finance department needs to review the annual budget before the upcoming board meeting.', 'Phòng tài chính cần xem xét ngân sách hàng năm trước cuộc họp hội đồng quản trị sắp tới.', '/uploads/audio/budget.wav', NOW(), NOW()) ON CONFLICT DO NOTHING;
INSERT INTO vocabularies (topic_id, word, phonetic, part_of_speech, meaning_vi, example_en, example_vi, audio_url, created_at, updated_at) VALUES ((SELECT id FROM topics WHERE name = 'Finance' LIMIT 1), 'profit', '/ˈprɑː.fɪt/', 'noun', 'lợi nhuận, tiền lãi', 'The company reported a significant increase in net profit during the third financial quarter.', 'Công ty đã báo cáo mức tăng trưởng đáng kể về lợi nhuận ròng trong quý tài chính thứ ba.', '/uploads/audio/profit.wav', NOW(), NOW()) ON CONFLICT DO NOTHING;
INSERT INTO vocabularies (topic_id, word, phonetic, part_of_speech, meaning_vi, example_en, example_vi, audio_url, created_at, updated_at) VALUES ((SELECT id FROM topics WHERE name = 'Finance' LIMIT 1), 'loss', '/lɔːs/', 'noun', 'khoản lỗ, sự tổn thất tài chính', 'The company reported a significant financial loss in the third quarter due to unexpected supply chain disruptions.', 'Công ty đã báo cáo một khoản lỗ tài chính đáng kể trong quý ba do sự gián đoạn chuỗi cung ứng ngoài dự kiến.', '/uploads/audio/loss.wav', NOW(), NOW()) ON CONFLICT DO NOTHING;
INSERT INTO vocabularies (topic_id, word, phonetic, part_of_speech, meaning_vi, example_en, example_vi, audio_url, created_at, updated_at) VALUES ((SELECT id FROM topics WHERE name = 'Finance' LIMIT 1), 'audit', '/ˈɑː.dɪt/', 'noun', 'kiểm toán, sự kiểm tra sổ sách kế toán', 'The independent accounting firm will conduct a thorough financial audit of our company next month.', 'Công ty kế toán độc lập sẽ tiến hành một cuộc kiểm toán tài chính kỹ lưỡng đối với công ty chúng tôi vào tháng tới.', '/uploads/audio/audit.wav', NOW(), NOW()) ON CONFLICT DO NOTHING;
INSERT INTO vocabularies (topic_id, word, phonetic, part_of_speech, meaning_vi, example_en, example_vi, audio_url, created_at, updated_at) VALUES ((SELECT id FROM topics WHERE name = 'Finance' LIMIT 1), 'asset', '/ˈæs.et/', 'noun', 'tài sản, vốn quý', 'The company''s total assets increased significantly following the successful acquisition of the smaller rival.', 'Tổng tài sản của công ty đã tăng đáng kể sau khi thâu tóm thành công đối thủ nhỏ hơn.', '/uploads/audio/asset.wav', NOW(), NOW()) ON CONFLICT DO NOTHING;
INSERT INTO vocabularies (topic_id, word, phonetic, part_of_speech, meaning_vi, example_en, example_vi, audio_url, created_at, updated_at) VALUES ((SELECT id FROM topics WHERE name = 'Finance' LIMIT 1), 'dividend', '/ˈdɪv.ə.dend/', 'noun', 'cổ tức', 'The board of directors decided to distribute a quarterly dividend to all shareholders next month.', 'Ban giám đốc đã quyết định phân phối cổ tức hàng quý cho tất cả cổ đông vào tháng tới.', '/uploads/audio/dividend.wav', NOW(), NOW()) ON CONFLICT DO NOTHING;
INSERT INTO vocabularies (topic_id, word, phonetic, part_of_speech, meaning_vi, example_en, example_vi, audio_url, created_at, updated_at) VALUES ((SELECT id FROM topics WHERE name = 'Finance' LIMIT 1), 'forecast', '/ˈfɔːr.kæst/', 'verb', 'dự báo, dự đoán (tài chính, doanh thu, v.x)', 'The finance department will forecast next quarter revenue during the urgent board meeting tomorrow.', 'Phòng tài chính sẽ dự báo doanh thu quý tới trong cuộc họp hội đồng quản trị khẩn cấp vào ngày mai.', '/uploads/audio/forecast.wav', NOW(), NOW()) ON CONFLICT DO NOTHING;
INSERT INTO vocabularies (topic_id, word, phonetic, part_of_speech, meaning_vi, example_en, example_vi, audio_url, created_at, updated_at) VALUES ((SELECT id FROM topics WHERE name = 'Finance' LIMIT 1), 'investment', '/ɪnˈvɛst.mənt/', 'noun', 'khoản đầu tư, sự đầu tư', 'The board of directors approved a significant investment in renewable energy projects this fiscal year.', 'Ban giám đốc đã phê duyệt một khoản đầu tư lớn vào các dự án năng lượng tái tạo trong năm tài chính này.', '/uploads/audio/investment.wav', NOW(), NOW()) ON CONFLICT DO NOTHING;
INSERT INTO vocabularies (topic_id, word, phonetic, part_of_speech, meaning_vi, example_en, example_vi, audio_url, created_at, updated_at) VALUES ((SELECT id FROM topics WHERE name = 'Finance' LIMIT 1), 'portfolio', '/ˌpɔːrtˈfoʊ.li.oʊ/', 'noun', 'danh mục đầu tư', 'The financial advisor recommended diversifying our investment portfolio to minimize potential risks in the volatile market.', 'Cố vấn tài chính khuyên nên đa dạng hóa danh mục đầu tư của chúng tôi để giảm thiểu rủi ro tiềm ẩn trong thị trường đầy biến động.', '/uploads/audio/portfolio.wav', NOW(), NOW()) ON CONFLICT DO NOTHING;
INSERT INTO vocabularies (topic_id, word, phonetic, part_of_speech, meaning_vi, example_en, example_vi, audio_url, created_at, updated_at) VALUES ((SELECT id FROM topics WHERE name = 'Finance' LIMIT 1), 'transaction', '/trænˈzæk.ʃən/', 'noun', 'giao dịch', 'All financial transactions must be recorded and approved by the accounting department before submission.', 'Tất cả các giao dịch tài chính phải được ghi lại và phê duyệt bởi phòng kế toán trước khi nộp.', '/uploads/audio/transaction.wav', NOW(), NOW()) ON CONFLICT DO NOTHING;
INSERT INTO vocabularies (topic_id, word, phonetic, part_of_speech, meaning_vi, example_en, example_vi, audio_url, created_at, updated_at) VALUES ((SELECT id FROM topics WHERE name = 'Finance' LIMIT 1), 'balance sheet', '/ˈbæl.əns ˌʃiːt/', 'noun', 'bảng cân đối kế toán', 'The chief financial officer presented the quarterly balance sheet during the board meeting this morning.', 'Giám đốc tài chính đã trình bày bảng cân đối kế toán hàng quý trong cuộc họp hội đồng quản trị sáng nay.', '/uploads/audio/balance_sheet.wav', NOW(), NOW()) ON CONFLICT DO NOTHING;
INSERT INTO vocabularies (topic_id, word, phonetic, part_of_speech, meaning_vi, example_en, example_vi, audio_url, created_at, updated_at) VALUES ((SELECT id FROM topics WHERE name = 'Finance' LIMIT 1), 'invoice', '/ˈɪn.vɔɪs/', 'noun', 'hóa đơn', 'The accounting department will process the vendor''s invoice upon receiving the verified delivery receipt.', 'Phòng kế toán sẽ xử lý hóa đơn của nhà cung cấp sau khi nhận được biên nhận giao hàng đã xác minh.', '/uploads/audio/invoice.wav', NOW(), NOW()) ON CONFLICT DO NOTHING;
INSERT INTO vocabularies (topic_id, word, phonetic, part_of_speech, meaning_vi, example_en, example_vi, audio_url, created_at, updated_at) VALUES ((SELECT id FROM topics WHERE name = 'Finance' LIMIT 1), 'receipt', '/rɪˈsiːt/', 'noun', 'biên lai, hóa đơn thanh toán', 'Please retain your original receipt to claim a full reimbursement for your business travel expenses next week.', 'Vui lòng giữ lại biên lai gốc của bạn để yêu cầu hoàn tiền đầy đủ cho các chi phí công tác vào tuần tới.', '/uploads/audio/receipt.wav', NOW(), NOW()) ON CONFLICT DO NOTHING;
INSERT INTO vocabularies (topic_id, word, phonetic, part_of_speech, meaning_vi, example_en, example_vi, audio_url, created_at, updated_at) VALUES ((SELECT id FROM topics WHERE name = 'Finance' LIMIT 1), 'interest rate', '/ˈɪn.trɪst reɪt/', 'noun', 'lãi suất', 'The central bank decided to lower the interest rate to stimulate economic growth this quarter.', 'Ngân hàng trung ương đã quyết định hạ lãi suất để kích thích tăng trưởng kinh tế trong quý này.', '/uploads/audio/interest_rate.wav', NOW(), NOW()) ON CONFLICT DO NOTHING;
INSERT INTO vocabularies (topic_id, word, phonetic, part_of_speech, meaning_vi, example_en, example_vi, audio_url, created_at, updated_at) VALUES ((SELECT id FROM topics WHERE name = 'Finance' LIMIT 1), 'inflation', '/ɪnˈfleɪ.ʃən/', 'noun', 'lạm phát', 'The central bank decided to raise interest rates to control rising inflation and stabilize the economy.', 'Ngân hàng trung ương đã quyết định tăng lãi suất để kiểm soát tình trạng lạm phát đang gia tăng và ổn định nền kinh tế.', '/uploads/audio/inflation.wav', NOW(), NOW()) ON CONFLICT DO NOTHING;
INSERT INTO vocabularies (topic_id, word, phonetic, part_of_speech, meaning_vi, example_en, example_vi, audio_url, created_at, updated_at) VALUES ((SELECT id FROM topics WHERE name = 'Finance' LIMIT 1), 'loan', '/loʊn/', 'noun', 'khoản vay', 'The corporate client applied for a large business loan to expand their manufacturing facilities.', 'Khách hàng doanh nghiệp đã nộp đơn xin một khoản vay kinh doanh lớn để mở rộng cơ sở sản xuất của họ.', '/uploads/audio/loan.wav', NOW(), NOW()) ON CONFLICT DO NOTHING;
INSERT INTO vocabularies (topic_id, word, phonetic, part_of_speech, meaning_vi, example_en, example_vi, audio_url, created_at, updated_at) VALUES ((SELECT id FROM topics WHERE name = 'Finance' LIMIT 1), 'mortgage', '/ˈmɔːr.ɡɪdʒ/', 'noun', 'khoản thế chấp, khoản vay mua nhà', 'The corporate finance department negotiated a lower interest rate for the new office building mortgage.', 'Phòng tài chính doanh nghiệp đã đàm phán một mức lãi suất thấp hơn cho khoản thế chấp tòa nhà văn phòng mới.', '/uploads/audio/mortgage.wav', NOW(), NOW()) ON CONFLICT DO NOTHING;
INSERT INTO vocabularies (topic_id, word, phonetic, part_of_speech, meaning_vi, example_en, example_vi, audio_url, created_at, updated_at) VALUES ((SELECT id FROM topics WHERE name = 'Finance' LIMIT 1), 'debt', '/dɛt/', 'noun', 'khoản nợ', 'The corporation plans to use its quarterly revenue to pay off its long-term debt.', 'Tập đoàn có kế hoạch sử dụng doanh thu hàng quý để trả khoản nợ dài hạn của mình.', '/uploads/audio/debt.wav', NOW(), NOW()) ON CONFLICT DO NOTHING;
INSERT INTO vocabularies (topic_id, word, phonetic, part_of_speech, meaning_vi, example_en, example_vi, audio_url, created_at, updated_at) VALUES ((SELECT id FROM topics WHERE name = 'Finance' LIMIT 1), 'bankrupt', '/ˈbæŋ.krʌpt/', 'adjective', 'phá sản, khánh tận', 'The manufacturing company went bankrupt after failing to secure a crucial loan from the bank.', 'Công ty sản xuất đã phá sản sau khi không thể đảm bảo một khoản vay quan trọng từ ngân hàng.', '/uploads/audio/bankrupt.wav', NOW(), NOW()) ON CONFLICT DO NOTHING;
INSERT INTO vocabularies (topic_id, word, phonetic, part_of_speech, meaning_vi, example_en, example_vi, audio_url, created_at, updated_at) VALUES ((SELECT id FROM topics WHERE name = 'Finance' LIMIT 1), 'capital', '/ˈkæp.ə.təl/', 'noun', 'vốn, tiền vốn', 'The startup company is currently seeking venture capital to fund its new software development project.', 'Công ty khởi nghiệp hiện đang tìm kiếm vốn mạo hiểm để tài trợ cho dự án phát triển phần mềm mới.', '/uploads/audio/capital.wav', NOW(), NOW()) ON CONFLICT DO NOTHING;
INSERT INTO vocabularies (topic_id, word, phonetic, part_of_speech, meaning_vi, example_en, example_vi, audio_url, created_at, updated_at) VALUES ((SELECT id FROM topics WHERE name = 'Finance' LIMIT 1), 'cash flow', '/ˈkæʃ ˌfloʊ/', 'noun', 'dòng tiền', 'The finance department implemented new cost-cutting measures to improve the company''s monthly cash flow.', 'Phòng tài chính đã thực hiện các biện pháp cắt giảm chi phí mới để cải thiện dòng tiền hàng tháng của công ty.', '/uploads/audio/cash_flow.wav', NOW(), NOW()) ON CONFLICT DO NOTHING;
INSERT INTO vocabularies (topic_id, word, phonetic, part_of_speech, meaning_vi, example_en, example_vi, audio_url, created_at, updated_at) VALUES ((SELECT id FROM topics WHERE name = 'Finance' LIMIT 1), 'fiscal year', '/ˈfɪs.kəl jɪr/', 'noun', 'năm tài chính', 'The corporation reported a significant increase in revenue during the final quarter of the fiscal year.', 'Tập đoàn đã báo cáo mức tăng trưởng doanh thu đáng kể trong quý cuối cùng của năm tài chính.', '/uploads/audio/fiscal_year.wav', NOW(), NOW()) ON CONFLICT DO NOTHING;
INSERT INTO vocabularies (topic_id, word, phonetic, part_of_speech, meaning_vi, example_en, example_vi, audio_url, created_at, updated_at) VALUES ((SELECT id FROM topics WHERE name = 'Finance' LIMIT 1), 'allocate', '/ˈæl.ə.keɪt/', 'verb', 'phân bổ, cấp phát (ngân sách, nguồn lực)', 'The finance department decided to allocate more funds for the upcoming marketing campaign next quarter.', 'Phòng tài chính đã quyết định phân bổ nhiều quỹ hơn cho chiến dịch tiếp thị sắp tới vào quý tới.', '/uploads/audio/allocate.wav', NOW(), NOW()) ON CONFLICT DO NOTHING;
INSERT INTO vocabularies (topic_id, word, phonetic, part_of_speech, meaning_vi, example_en, example_vi, audio_url, created_at, updated_at) VALUES ((SELECT id FROM topics WHERE name = 'Finance' LIMIT 1), 'currency', '/ˈkɜːr.ən.si/', 'noun', 'tiền tệ, đơn vị tiền tệ', 'The finance department closely monitors currency fluctuations to minimize risks when conducting international transactions.', 'Bộ phận tài chính theo dõi chặt chẽ sự biến động tiền tệ để giảm thiểu rủi ro khi thực hiện các giao dịch quốc tế.', '/uploads/audio/currency.wav', NOW(), NOW()) ON CONFLICT DO NOTHING;
INSERT INTO vocabularies (topic_id, word, phonetic, part_of_speech, meaning_vi, example_en, example_vi, audio_url, created_at, updated_at) VALUES ((SELECT id FROM topics WHERE name = 'Finance' LIMIT 1), 'quarterly', '/ˈkwɔːr.t̬ɚ.li/', 'adjective', 'hàng quý, diễn ra bốn lần một năm', 'The finance department is preparing the quarterly financial report for the upcoming board meeting.', 'Bộ phận tài chính đang chuẩn bị báo cáo tài chính hàng quý cho cuộc họp hội đồng quản trị sắp tới.', '/uploads/audio/quarterly.wav', NOW(), NOW()) ON CONFLICT DO NOTHING;
INSERT INTO vocabularies (topic_id, word, phonetic, part_of_speech, meaning_vi, example_en, example_vi, audio_url, created_at, updated_at) VALUES ((SELECT id FROM topics WHERE name = 'Finance' LIMIT 1), 'deficit', '/ˈdef.ɪ.sɪt/', 'noun', 'thâm hụt, số tiền thiếu hụt', 'The finance department is working hard to reduce the operating deficit before the fiscal year ends.', 'Phòng tài chính đang nỗ lực làm việc để giảm khoản thâm hụt hoạt động trước khi năm tài chính kết thúc.', '/uploads/audio/deficit.wav', NOW(), NOW()) ON CONFLICT DO NOTHING;
INSERT INTO vocabularies (topic_id, word, phonetic, part_of_speech, meaning_vi, example_en, example_vi, audio_url, created_at, updated_at) VALUES ((SELECT id FROM topics WHERE name = 'Finance' LIMIT 1), 'surplus', '/ˈsɝː.pləs/', 'noun', 'số dư, thặng dư', 'The finance department plans to reinvest the quarterly budget surplus into new software licenses.', 'Phòng tài chính có kế hoạch tái đầu tư khoản ngân sách thặng dư hàng quý vào các giấy phép phần mềm mới.', '/uploads/audio/surplus.wav', NOW(), NOW()) ON CONFLICT DO NOTHING;
INSERT INTO vocabularies (topic_id, word, phonetic, part_of_speech, meaning_vi, example_en, example_vi, audio_url, created_at, updated_at) VALUES ((SELECT id FROM topics WHERE name = 'Marketing' LIMIT 1), 'compare', '/kəmˈper/', 'verb', 'so sánh, đối chiếu', 'The marketing team needs to compare our competitor''s pricing strategy with ours before launching the new advertising campaign.', 'Đội ngũ tiếp thị cần so sánh chiến lược định giá của đối thủ cạnh tranh với của chúng ta trước khi khởi động chiến dịch quảng cáo mới.', '/uploads/audio/compare.wav', NOW(), NOW()) ON CONFLICT DO NOTHING;
INSERT INTO vocabularies (topic_id, word, phonetic, part_of_speech, meaning_vi, example_en, example_vi, audio_url, created_at, updated_at) VALUES ((SELECT id FROM topics WHERE name = 'Marketing' LIMIT 1), 'competition', '/ˌkɑːm.pəˈtɪʃ.ən/', 'noun', 'sự cạnh tranh, đối thủ cạnh tranh', 'Our marketing team must develop a creative strategy to outperform the intense competition in the industry.', 'Đội ngũ tiếp thị của chúng tôi phải phát triển một chiến lược sáng tạo để vượt qua sự cạnh tranh khốc liệt trong ngành.', '/uploads/audio/competition.wav', NOW(), NOW()) ON CONFLICT DO NOTHING;
INSERT INTO vocabularies (topic_id, word, phonetic, part_of_speech, meaning_vi, example_en, example_vi, audio_url, created_at, updated_at) VALUES ((SELECT id FROM topics WHERE name = 'Marketing' LIMIT 1), 'consume', '/kənˈsuːm/', 'verb', 'tiêu thụ, tiêu dùng', 'Our new marketing campaign aims to persuade younger demographics to consume organic snacks.', 'Chiến dịch tiếp thị mới của chúng tôi nhằm thuyết phục nhân khẩu học trẻ tuổi tiêu thụ đồ ăn vặt hữu cơ.', '/uploads/audio/consume.wav', NOW(), NOW()) ON CONFLICT DO NOTHING;
INSERT INTO vocabularies (topic_id, word, phonetic, part_of_speech, meaning_vi, example_en, example_vi, audio_url, created_at, updated_at) VALUES ((SELECT id FROM topics WHERE name = 'Marketing' LIMIT 1), 'convince', '/kənˈvɪns/', 'verb', 'thuyết phục', 'The marketing team worked hard to convince consumers to buy the new eco-friendly product.', 'Đội ngũ marketing đã làm việc chăm chỉ để thuyết phục người tiêu dùng mua sản phẩm thân thiện với môi trường mới.', '/uploads/audio/convince.wav', NOW(), NOW()) ON CONFLICT DO NOTHING;
INSERT INTO vocabularies (topic_id, word, phonetic, part_of_speech, meaning_vi, example_en, example_vi, audio_url, created_at, updated_at) VALUES ((SELECT id FROM topics WHERE name = 'Marketing' LIMIT 1), 'currently', '/ˈkɜːr.ənt.li/', 'adverb', 'hiện tại, hiện thời', 'We are currently running a promotional campaign on social media to increase our brand awareness among young consumers.', 'Chúng tôi hiện đang triển khai một chiến dịch quảng bá trên mạng xã hội để tăng cường nhận diện thương hiệu đối với những người tiêu dùng trẻ.', '/uploads/audio/currently.wav', NOW(), NOW()) ON CONFLICT DO NOTHING;
INSERT INTO vocabularies (topic_id, word, phonetic, part_of_speech, meaning_vi, example_en, example_vi, audio_url, created_at, updated_at) VALUES ((SELECT id FROM topics WHERE name = 'Marketing' LIMIT 1), 'fad', '/fæd/', 'noun', 'mốt nhất thời, sự cuồng nhiệt tạm thời', 'The marketing team realized that the recent surge in consumer interest was just a temporary fad.', 'Nhóm marketing nhận ra rằng sự gia tăng sự quan tâm của người tiêu dùng gần đây chỉ là một trào lưu nhất thời.', '/uploads/audio/fad.wav', NOW(), NOW()) ON CONFLICT DO NOTHING;
INSERT INTO vocabularies (topic_id, word, phonetic, part_of_speech, meaning_vi, example_en, example_vi, audio_url, created_at, updated_at) VALUES ((SELECT id FROM topics WHERE name = 'Marketing' LIMIT 1), 'inspiration', '/ˌɪn.spəˈreɪ.ʃən/', 'noun', 'cảm hứng, nguồn cảm hứng', 'The creative team found fresh inspiration for the upcoming digital marketing campaign during the morning workshop.', 'Nhóm sáng tạo đã tìm thấy nguồn cảm hứng mới cho chiến dịch tiếp thị kỹ thuật số sắp tới trong buổi hội thảo buổi sáng.', '/uploads/audio/inspiration.wav', NOW(), NOW()) ON CONFLICT DO NOTHING;
INSERT INTO vocabularies (topic_id, word, phonetic, part_of_speech, meaning_vi, example_en, example_vi, audio_url, created_at, updated_at) VALUES ((SELECT id FROM topics WHERE name = 'Marketing' LIMIT 1), 'market', '/ˈmɑːr.kɪt/', 'noun', 'thị trường', 'Our marketing team is developing a new strategy to expand into the Asian market next quarter.', 'Đội ngũ tiếp thị của chúng tôi đang phát triển một chiến lược mới để mở rộng sang thị trường châu Á vào quý tới.', '/uploads/audio/market.wav', NOW(), NOW()) ON CONFLICT DO NOTHING;
INSERT INTO vocabularies (topic_id, word, phonetic, part_of_speech, meaning_vi, example_en, example_vi, audio_url, created_at, updated_at) VALUES ((SELECT id FROM topics WHERE name = 'Marketing' LIMIT 1), 'persuasion', '/pərˈswāzhən/', 'noun', 'sự thuyết phục', 'The marketing team used subtle persuasion techniques to increase consumer interest in the new product.', 'Đội ngũ marketing đã sử dụng các kỹ thuật thuyết phục tinh tế để tăng sự quan tâm của người tiêu dùng đối với sản phẩm mới.', '/uploads/audio/persuasion.wav', NOW(), NOW()) ON CONFLICT DO NOTHING;
INSERT INTO vocabularies (topic_id, word, phonetic, part_of_speech, meaning_vi, example_en, example_vi, audio_url, created_at, updated_at) VALUES ((SELECT id FROM topics WHERE name = 'Marketing' LIMIT 1), 'productive', '/prəˈdʌk.tɪv/', 'adjective', 'năng suất cao, hiệu quả, hữu ích', 'The marketing team held a long meeting to ensure the new advertising campaign would be productive.', 'Nhóm marketing đã tổ chức một cuộc họp dài để đảm bảo chiến dịch quảng cáo mới sẽ mang lại hiệu quả cao.', '/uploads/audio/productive.wav', NOW(), NOW()) ON CONFLICT DO NOTHING;
INSERT INTO vocabularies (topic_id, word, phonetic, part_of_speech, meaning_vi, example_en, example_vi, audio_url, created_at, updated_at) VALUES ((SELECT id FROM topics WHERE name = 'Marketing' LIMIT 1), 'campaign', '/kæmˈpeɪn/', 'noun', 'chiến dịch quảng cáo/thường mại', 'The marketing department launched a new digital campaign to increase brand awareness among young professionals.', 'Phòng marketing đã tung ra một chiến dịch kỹ thuật số mới để nâng cao nhận thức về thương hiệu trong giới chuyên gia trẻ.', '/uploads/audio/campaign.wav', NOW(), NOW()) ON CONFLICT DO NOTHING;
INSERT INTO vocabularies (topic_id, word, phonetic, part_of_speech, meaning_vi, example_en, example_vi, audio_url, created_at, updated_at) VALUES ((SELECT id FROM topics WHERE name = 'Marketing' LIMIT 1), 'demographic', '/ˌdɛm.əˈɡræf.ɪk/', 'noun', 'nhóm nhân khẩu học, tập khách hàng mục tiêu', 'Our marketing team is currently analyzing the younger demographic to launch the new smartphone campaign.', 'Đội ngũ tiếp thị của chúng tôi hiện đang phân tích nhóm nhân khẩu học trẻ tuổi để khởi động chiến dịch điện thoại thông minh mới.', '/uploads/audio/demographic.wav', NOW(), NOW()) ON CONFLICT DO NOTHING;
INSERT INTO vocabularies (topic_id, word, phonetic, part_of_speech, meaning_vi, example_en, example_vi, audio_url, created_at, updated_at) VALUES ((SELECT id FROM topics WHERE name = 'Marketing' LIMIT 1), 'promote', '/prəˈmoʊt/', 'verb', 'quảng bá, quảng cáo', 'The marketing department launched a new digital campaign to promote the latest eco-friendly product.', 'Bộ phận marketing đã tung ra một chiến dịch kỹ thuật số mới để quảng bá sản phẩm thân thiện với môi trường mới nhất.', '/uploads/audio/promote.wav', NOW(), NOW()) ON CONFLICT DO NOTHING;
INSERT INTO vocabularies (topic_id, word, phonetic, part_of_speech, meaning_vi, example_en, example_vi, audio_url, created_at, updated_at) VALUES ((SELECT id FROM topics WHERE name = 'Marketing' LIMIT 1), 'launch', '/lɔːntʃ/', 'verb', 'ra mắt, tung ra thị trường', 'The marketing department will launch a new advertising campaign for our latest smartphone next month.', 'Phòng marketing sẽ ra mắt một chiến dịch quảng cáo mới cho chiếc điện thoại thông minh mới nhất của chúng ta vào tháng tới.', '/uploads/audio/launch.wav', NOW(), NOW()) ON CONFLICT DO NOTHING;
INSERT INTO vocabularies (topic_id, word, phonetic, part_of_speech, meaning_vi, example_en, example_vi, audio_url, created_at, updated_at) VALUES ((SELECT id FROM topics WHERE name = 'Marketing' LIMIT 1), 'target audience', '/ˈtɑːrɡɪt ˈɔːdiəns/', 'noun', 'khách hàng mục tiêu', 'The marketing team designed a new digital campaign specifically to attract our target audience.', 'Đội ngũ tiếp thị đã thiết kế một chiến dịch kỹ thuật số mới đặc biệt để thu hút khách hàng mục tiêu của chúng ta.', '/uploads/audio/target_audience.wav', NOW(), NOW()) ON CONFLICT DO NOTHING;
INSERT INTO vocabularies (topic_id, word, phonetic, part_of_speech, meaning_vi, example_en, example_vi, audio_url, created_at, updated_at) VALUES ((SELECT id FROM topics WHERE name = 'Marketing' LIMIT 1), 'brand awareness', '/brænd əˈwer.nəs/', 'noun', 'độ nhận diện thương hiệu', 'The marketing team launched a new social media campaign to increase brand awareness among younger consumers.', 'Nhóm marketing đã tung ra một chiến dịch truyền thông xã hội mới để tăng độ nhận diện thương hiệu trong giới trẻ tiêu dùng.', '/uploads/audio/brand_awareness.wav', NOW(), NOW()) ON CONFLICT DO NOTHING;
INSERT INTO vocabularies (topic_id, word, phonetic, part_of_speech, meaning_vi, example_en, example_vi, audio_url, created_at, updated_at) VALUES ((SELECT id FROM topics WHERE name = 'Marketing' LIMIT 1), 'endorse', '/ɪnˈdɔːrs/', 'verb', 'quảng cáo, tán thành, xác nhận (người nổi tiếng quảng bá sản phẩm)', 'Several popular athletes were hired to endorse our new athletic footwear brand globally.', 'Một số vận động viên nổi tiếng đã được thuê để quảng bá thương hiệu giày thể thao mới của chúng tôi trên toàn cầu.', '/uploads/audio/endorse.wav', NOW(), NOW()) ON CONFLICT DO NOTHING;
INSERT INTO vocabularies (topic_id, word, phonetic, part_of_speech, meaning_vi, example_en, example_vi, audio_url, created_at, updated_at) VALUES ((SELECT id FROM topics WHERE name = 'Marketing' LIMIT 1), 'leaflet', '/ˈliː.flət/', 'noun', 'tờ rơi quảng cáo', 'The marketing team distributed promotional leaflets to attract more customers for the grand opening.', 'Đội ngũ tiếp thị đã phát các tờ rơi quảng cáo để thu hút thêm khách hàng cho lễ khai trương.', '/uploads/audio/leaflet.wav', NOW(), NOW()) ON CONFLICT DO NOTHING;
INSERT INTO vocabularies (topic_id, word, phonetic, part_of_speech, meaning_vi, example_en, example_vi, audio_url, created_at, updated_at) VALUES ((SELECT id FROM topics WHERE name = 'Marketing' LIMIT 1), 'commercial', '/kəˈmɝː.ʃəl/', 'adjective', 'thương mại, quảng cáo thương mại', 'The marketing department launched a new commercial campaign to promote our latest smartphone model.', 'Phòng marketing đã triển khai một chiến dịch thương mại mới nhằm quảng bá mẫu điện thoại thông minh mới nhất của chúng tôi.', '/uploads/audio/commercial.wav', NOW(), NOW()) ON CONFLICT DO NOTHING;
INSERT INTO vocabularies (topic_id, word, phonetic, part_of_speech, meaning_vi, example_en, example_vi, audio_url, created_at, updated_at) VALUES ((SELECT id FROM topics WHERE name = 'Marketing' LIMIT 1), 'penetration', '/ˌpɛn.əˈtreɪ.ʃən/', 'noun', 'sự thâm nhập thị trường', 'Our latest marketing strategy aims to increase market penetration in the Asian region significantly.', 'Chiến lược tiếp thị mới nhất của chúng tôi nhằm mục đích tăng đáng kể sự thâm nhập thị trường ở khu vực châu Á.', '/uploads/audio/penetration.wav', NOW(), NOW()) ON CONFLICT DO NOTHING;
INSERT INTO vocabularies (topic_id, word, phonetic, part_of_speech, meaning_vi, example_en, example_vi, audio_url, created_at, updated_at) VALUES ((SELECT id FROM topics WHERE name = 'Marketing' LIMIT 1), 'sponsor', '/ˈspɑːn.sɚ/', 'verb', 'tài trợ', 'Our company decided to sponsor the upcoming digital marketing conference to increase brand awareness.', 'Công ty chúng tôi quyết định tài trợ cho hội nghị tiếp thị kỹ thuật số sắp tới để nâng cao nhận ức thương hiệu.', '/uploads/audio/sponsor.wav', NOW(), NOW()) ON CONFLICT DO NOTHING;
INSERT INTO vocabularies (topic_id, word, phonetic, part_of_speech, meaning_vi, example_en, example_vi, audio_url, created_at, updated_at) VALUES ((SELECT id FROM topics WHERE name = 'Marketing' LIMIT 1), 'billboard', '/ˈbɪl.bɔːrd/', 'noun', 'biển quảng cáo ngoài trời', 'The marketing team decided to place a large billboard near the highway to promote our new product.', 'Đội ngũ tiếp thị đã quyết định đặt một biển quảng cáo lớn gần đường cao tốc để quảng bá sản phẩm mới của chúng tôi.', '/uploads/audio/billboard.wav', NOW(), NOW()) ON CONFLICT DO NOTHING;
INSERT INTO vocabularies (topic_id, word, phonetic, part_of_speech, meaning_vi, example_en, example_vi, audio_url, created_at, updated_at) VALUES ((SELECT id FROM topics WHERE name = 'Marketing' LIMIT 1), 'strategy', '/ˈstræt.ə.dʒi/', 'noun', 'chiến lược', 'The marketing team proposed a new social media strategy to increase our brand awareness globally.', 'Đội ngũ tiếp thị đã đề xuất một chiến lược mạng xã hội mới để tăng nhận diện thương hiệu của chúng ta trên toàn cầu.', '/uploads/audio/strategy.wav', NOW(), NOW()) ON CONFLICT DO NOTHING;
INSERT INTO vocabularies (topic_id, word, phonetic, part_of_speech, meaning_vi, example_en, example_vi, audio_url, created_at, updated_at) VALUES ((SELECT id FROM topics WHERE name = 'Marketing' LIMIT 1), 'preference', '/ˈprɛf.ər.əns/', 'noun', 'sự ưu tiên, sở thích', 'Please complete the online survey to share your brand preference for our upcoming marketing campaign.', 'Vui lòng hoàn thành khảo sát trực tuyến để chia sẻ sở thích thương hiệu của bạn cho chiến dịch tiếp thị sắp tới của chúng tôi.', '/uploads/audio/preference.wav', NOW(), NOW()) ON CONFLICT DO NOTHING;
INSERT INTO vocabularies (topic_id, word, phonetic, part_of_speech, meaning_vi, example_en, example_vi, audio_url, created_at, updated_at) VALUES ((SELECT id FROM topics WHERE name = 'Marketing' LIMIT 1), 'potential', '/pəˈten.ʃəl/', 'noun', 'tiềm năng, khả năng phát triển', 'The marketing team analyzed the market to identify potential customers for the new product launch.', 'Nhóm tiếp thị đã phân tích thị trường để xác định khách hàng tiềm năng cho việc ra mắt sản phẩm mới.', '/uploads/audio/potential.wav', NOW(), NOW()) ON CONFLICT DO NOTHING;
INSERT INTO vocabularies (topic_id, word, phonetic, part_of_speech, meaning_vi, example_en, example_vi, audio_url, created_at, updated_at) VALUES ((SELECT id FROM topics WHERE name = 'Marketing' LIMIT 1), 'influence', '/ˈɪn.flu.əns/', 'noun', 'sự ảnh hưởng, sức ảnh hưởng', 'Celebrity endorsements can significantly influence consumer purchasing behavior in our upcoming marketing campaign.', 'Sự chứng thực của người nổi tiếng có thể tác động đáng kể đến hành vi mua sắm của người tiêu dùng trong chiến dịch tiếp thị sắp tới của chúng ta.', '/uploads/audio/influence.wav', NOW(), NOW()) ON CONFLICT DO NOTHING;
INSERT INTO vocabularies (topic_id, word, phonetic, part_of_speech, meaning_vi, example_en, example_vi, audio_url, created_at, updated_at) VALUES ((SELECT id FROM topics WHERE name = 'Marketing' LIMIT 1), 'niche', '/nɪtʃ/', 'noun', 'thị trường ngách', 'Our marketing team decided to target a specific niche for the new organic skincare product line.', 'Đội ngũ marketing của chúng tôi quyết định nhắm đến một thị trường ngách cụ thể cho dòng sản phẩm chăm sóc da hữu cơ mới.', '/uploads/audio/niche.wav', NOW(), NOW()) ON CONFLICT DO NOTHING;
INSERT INTO vocabularies (topic_id, word, phonetic, part_of_speech, meaning_vi, example_en, example_vi, audio_url, created_at, updated_at) VALUES ((SELECT id FROM topics WHERE name = 'Office' LIMIT 1), 'agenda', '/əˈdʒen.də/', 'noun', 'chương trình nghị sự, lịch trình cuộc họp', 'Please review the attached agenda before attending the quarterly management meeting tomorrow morning.', 'Vui lòng xem lại chương trình nghị sự được đính kèm trước khi tham dự cuộc họp quản lý hàng quý vào sáng mai.', '/uploads/audio/agenda.wav', NOW(), NOW()) ON CONFLICT DO NOTHING;
INSERT INTO vocabularies (topic_id, word, phonetic, part_of_speech, meaning_vi, example_en, example_vi, audio_url, created_at, updated_at) VALUES ((SELECT id FROM topics WHERE name = 'Office' LIMIT 1), 'memo', '/ˈmem.oʊ/', 'noun', 'bản ghi nhớ, thông báo nội bộ', 'The department manager sent a memo to all employees regarding the upcoming office renovation schedule.', 'Trưởng phòng đã gửi một bản ghi nhớ cho tất cả nhân viên liên quan đến lịch trình cải tạo văn phòng sắp tới.', '/uploads/audio/memo.wav', NOW(), NOW()) ON CONFLICT DO NOTHING;
INSERT INTO vocabularies (topic_id, word, phonetic, part_of_speech, meaning_vi, example_en, example_vi, audio_url, created_at, updated_at) VALUES ((SELECT id FROM topics WHERE name = 'Office' LIMIT 1), 'minutes', '/ˈmɪn.ɪts/', 'noun', 'biên bản cuộc họp', 'The secretary will distribute the meeting minutes to all department heads by tomorrow morning.', 'Thư ký sẽ phân phát biên bản cuộc họp cho tất cả các trưởng phòng trước sáng mai.', '/uploads/audio/minutes.wav', NOW(), NOW()) ON CONFLICT DO NOTHING;
INSERT INTO vocabularies (topic_id, word, phonetic, part_of_speech, meaning_vi, example_en, example_vi, audio_url, created_at, updated_at) VALUES ((SELECT id FROM topics WHERE name = 'Office' LIMIT 1), 'conference', '/ˈkɑːn.fɚ.əns/', 'noun', 'hội nghị, cuộc họp', 'All department managers must attend the annual conference in the main boardroom tomorrow morning.', 'Tất cả các trưởng phòng phải tham gia hội nghị thường niên tại phòng họp chính vào sáng ngày mai.', '/uploads/audio/conference.wav', NOW(), NOW()) ON CONFLICT DO NOTHING;
INSERT INTO vocabularies (topic_id, word, phonetic, part_of_speech, meaning_vi, example_en, example_vi, audio_url, created_at, updated_at) VALUES ((SELECT id FROM topics WHERE name = 'Office' LIMIT 1), 'facility', '/fəˈsɪl.ə.t̬i/', 'noun', 'cơ sở vật chất, thiết bị, tiện nghi', 'All employees are requested to keep the new office facility clean and orderly at all times.', 'Tất cả nhân viên được yêu cầu giữ gìn cơ sở vật chất văn phòng mới luôn sạch sẽ và ngăn nắp.', '/uploads/audio/facility.wav', NOW(), NOW()) ON CONFLICT DO NOTHING;
INSERT INTO vocabularies (topic_id, word, phonetic, part_of_speech, meaning_vi, example_en, example_vi, audio_url, created_at, updated_at) VALUES ((SELECT id FROM topics WHERE name = 'Office' LIMIT 1), 'equipment', '/ɪˈkwɪp.mənt/', 'noun', 'thiết bị, dụng cụ', 'All employees must report any malfunctioning office equipment to the administration department immediately.', 'Tất cả nhân viên phải báo cáo ngay bất kỳ thiết bị văn phòng nào bị hỏng cho phòng hành chính.', '/uploads/audio/equipment.wav', NOW(), NOW()) ON CONFLICT DO NOTHING;
INSERT INTO vocabularies (topic_id, word, phonetic, part_of_speech, meaning_vi, example_en, example_vi, audio_url, created_at, updated_at) VALUES ((SELECT id FROM topics WHERE name = 'Office' LIMIT 1), 'maintenance', '/ˈmeɪn.tən.əns/', 'noun', 'sự bảo trì, sự bảo dưỡng', 'Regular maintenance of office equipment helps prevent unexpected breakdowns during important business hours.', 'Việc bảo trì thường xuyên thiết bị văn phòng giúp ngăn ngừa các sự cố hỏng hóc bất ngờ trong giờ làm việc quan trọng.', '/uploads/audio/maintenance.wav', NOW(), NOW()) ON CONFLICT DO NOTHING;
INSERT INTO vocabularies (topic_id, word, phonetic, part_of_speech, meaning_vi, example_en, example_vi, audio_url, created_at, updated_at) VALUES ((SELECT id FROM topics WHERE name = 'Office' LIMIT 1), 'troubleshoot', '/ˈtrʌb.əl.ʃuːt/', 'verb', 'khắc phục sự cố, giải quyết vấn đề kỹ thuật', 'Our IT department is available to troubleshoot any network issues you might encounter today.', 'Bộ phận IT của chúng tôi luôn sẵn sàng khắc phục mọi sự cố mạng mà bạn có thể gặp phải hôm nay.', '/uploads/audio/troubleshoot.wav', NOW(), NOW()) ON CONFLICT DO NOTHING;
INSERT INTO vocabularies (topic_id, word, phonetic, part_of_speech, meaning_vi, example_en, example_vi, audio_url, created_at, updated_at) VALUES ((SELECT id FROM topics WHERE name = 'Office' LIMIT 1), 'compatible', '/kəmˈpæt̬.ə.bəl/', 'adjective', 'tương thích', 'Please ensure that the new accounting software is compatible with our current office computers.', 'Vui lòng đảm bảo rằng phần mềm kế toán mới tương thích với các máy tính văn phòng hiện tại của chúng ta.', '/uploads/audio/compatible.wav', NOW(), NOW()) ON CONFLICT DO NOTHING;
INSERT INTO vocabularies (topic_id, word, phonetic, part_of_speech, meaning_vi, example_en, example_vi, audio_url, created_at, updated_at) VALUES ((SELECT id FROM topics WHERE name = 'Office' LIMIT 1), 'network', '/ˈnet.wɜːrk/', 'noun', 'mạng lưới, hệ thống mạng', 'Our IT department is currently upgrading the office computer network to improve data security.', 'Phòng công nghệ thông tin của chúng tôi hiện đang nâng cấp mạng máy tính văn phòng để cải thiện bảo mật dữ liệu.', '/uploads/audio/network.wav', NOW(), NOW()) ON CONFLICT DO NOTHING;
INSERT INTO vocabularies (topic_id, word, phonetic, part_of_speech, meaning_vi, example_en, example_vi, audio_url, created_at, updated_at) VALUES ((SELECT id FROM topics WHERE name = 'Office' LIMIT 1), 'server', '/ˈsɝː.vɚ/', 'noun', 'máy chủ', 'The IT department will upgrade the main server this weekend to improve network performance.', 'Phòng công nghệ thông tin sẽ nâng cấp máy chủ chính vào cuối tuần này để cải thiện hiệu suất mạng.', '/uploads/audio/server.wav', NOW(), NOW()) ON CONFLICT DO NOTHING;
INSERT INTO vocabularies (topic_id, word, phonetic, part_of_speech, meaning_vi, example_en, example_vi, audio_url, created_at, updated_at) VALUES ((SELECT id FROM topics WHERE name = 'Office' LIMIT 1), 'software', '/ˈsɔːft.wer/', 'noun', 'phần mềm', 'All employees are required to install the new accounting software on their office computers by Friday.', 'Tất cả nhân viên được yêu cầu cài đặt phần mềm kế toán mới trên máy tính văn phòng trước thứ Sáu.', '/uploads/audio/software.wav', NOW(), NOW()) ON CONFLICT DO NOTHING;
INSERT INTO vocabularies (topic_id, word, phonetic, part_of_speech, meaning_vi, example_en, example_vi, audio_url, created_at, updated_at) VALUES ((SELECT id FROM topics WHERE name = 'Office' LIMIT 1), 'hardware', '/ˈhɑːrd.wer/', 'noun', 'phần cứng (máy tính, thiết bị văn phòng)', 'The IT department is upgrading the office hardware to improve overall system performance and speed.', 'Bộ phận CNTT đang nâng cấp phần cứng văn phòng để cải thiện hiệu suất và tốc độ của toàn bộ hệ thống.', '/uploads/audio/hardware.wav', NOW(), NOW()) ON CONFLICT DO NOTHING;
INSERT INTO vocabularies (topic_id, word, phonetic, part_of_speech, meaning_vi, example_en, example_vi, audio_url, created_at, updated_at) VALUES ((SELECT id FROM topics WHERE name = 'Office' LIMIT 1), 'update', '/ˈʌp.deɪt/', 'verb', 'cập nhật', 'Please ensure you update your contact information in the company directory before Friday.', 'Vui lòng đảm bảo bạn cập nhật thông tin liên lạc của mình trong danh bạ công ty trước thứ Sáu.', '/uploads/audio/update.wav', NOW(), NOW()) ON CONFLICT DO NOTHING;
INSERT INTO vocabularies (topic_id, word, phonetic, part_of_speech, meaning_vi, example_en, example_vi, audio_url, created_at, updated_at) VALUES ((SELECT id FROM topics WHERE name = 'Office' LIMIT 1), 'install', '/ɪnˈstɔːl/', 'verb', 'lắp đặt, cài đặt', 'The IT department will install the new software on all office computers this weekend.', 'Phòng IT sẽ cài đặt phần mềm mới trên tất cả máy tính văn phòng vào cuối tuần này.', '/uploads/audio/install.wav', NOW(), NOW()) ON CONFLICT DO NOTHING;
INSERT INTO vocabularies (topic_id, word, phonetic, part_of_speech, meaning_vi, example_en, example_vi, audio_url, created_at, updated_at) VALUES ((SELECT id FROM topics WHERE name = 'Office' LIMIT 1), 'confidential', '/ˌkɑːn.fɪˈden.ʃəl/', 'adjective', 'bảo mật, kín', 'Please ensure that all financial reports remain strictly confidential before the board meeting tomorrow.', 'Vui lòng đảm bảo rằng tất cả các báo cáo tài chính được giữ bảo mật nghiêm ngặt trước cuộc họp hội đồng quản trị vào ngày mai.', '/uploads/audio/confidential.wav', NOW(), NOW()) ON CONFLICT DO NOTHING;
INSERT INTO vocabularies (topic_id, word, phonetic, part_of_speech, meaning_vi, example_en, example_vi, audio_url, created_at, updated_at) VALUES ((SELECT id FROM topics WHERE name = 'Office' LIMIT 1), 'shred', '/ʃrɛd/', 'verb', 'cắt nhỏ, hủy tài liệu', 'Employees are required to shred all confidential documents before throwing them into the recycling bins.', 'Nhân viên được yêu cầu hủy tất cả các tài liệu mật trước khi vứt chúng vào thùng tái chế.', '/uploads/audio/shred.wav', NOW(), NOW()) ON CONFLICT DO NOTHING;
INSERT INTO vocabularies (topic_id, word, phonetic, part_of_speech, meaning_vi, example_en, example_vi, audio_url, created_at, updated_at) VALUES ((SELECT id FROM topics WHERE name = 'Office' LIMIT 1), 'archive', '/ˈɑːr.kaɪv/', 'verb', 'lưu trữ (tài liệu, tệp tin)', 'Please archive all outdated project files in the shared digital storage system before Friday afternoon.', 'Vui lòng lưu trữ tất cả các tệp dự án cũ trong hệ thống lưu trữ kỹ thuật số chung trước chiều thứ Sáu.', '/uploads/audio/archive.wav', NOW(), NOW()) ON CONFLICT DO NOTHING;
INSERT INTO vocabularies (topic_id, word, phonetic, part_of_speech, meaning_vi, example_en, example_vi, audio_url, created_at, updated_at) VALUES ((SELECT id FROM topics WHERE name = 'Office' LIMIT 1), 'stationery', '/ˈsteɪ.ʃə.ner.i/', 'noun', 'đồ dùng văn phòng phẩm', 'Please submit your monthly request for office stationery to the administrative department by Friday.', 'Vui lòng gửi yêu cầu đặt mua văn phòng phẩm hàng tháng cho phòng hành chính trước thứ Sáu.', '/uploads/audio/stationery.wav', NOW(), NOW()) ON CONFLICT DO NOTHING;
INSERT INTO vocabularies (topic_id, word, phonetic, part_of_speech, meaning_vi, example_en, example_vi, audio_url, created_at, updated_at) VALUES ((SELECT id FROM topics WHERE name = 'Office' LIMIT 1), 'supply', '/səˈplaɪ/', 'noun', 'vật tư, đồ dùng văn phòng', 'Please submit your monthly office supply requests to the administration department before Friday afternoon.', 'Vui lòng gửi các yêu cầu về vật tư văn phòng hàng tháng của bạn cho phòng hành chính trước chiều thứ Sáu.', '/uploads/audio/supply.wav', NOW(), NOW()) ON CONFLICT DO NOTHING;
INSERT INTO vocabularies (topic_id, word, phonetic, part_of_speech, meaning_vi, example_en, example_vi, audio_url, created_at, updated_at) VALUES ((SELECT id FROM topics WHERE name = 'Office' LIMIT 1), 'bulletin board', '/ˈbʊl.ə.tɪn ˌbɔːrd/', 'noun', 'bảng thông báo', 'Please check the bulletin board in the breakroom for the updated company holiday schedule.', 'Vui lòng kiểm tra bảng thông báo ở phòng nghỉ để xem lịch nghỉ lễ cập nhật của công ty.', '/uploads/audio/bulletin_board.wav', NOW(), NOW()) ON CONFLICT DO NOTHING;
INSERT INTO vocabularies (topic_id, word, phonetic, part_of_speech, meaning_vi, example_en, example_vi, audio_url, created_at, updated_at) VALUES ((SELECT id FROM topics WHERE name = 'Office' LIMIT 1), 'collaborate', '/kəˈlæb.ə.reɪt/', 'verb', 'hợp tác, cộng tác', 'The marketing and sales departments must collaborate closely to launch the new office software.', 'Phòng tiếp thị và phòng kinh doanh phải hợp tác chặt chẽ để ra mắt phần mềm văn phòng mới.', '/uploads/audio/collaborate.wav', NOW(), NOW()) ON CONFLICT DO NOTHING;
INSERT INTO vocabularies (topic_id, word, phonetic, part_of_speech, meaning_vi, example_en, example_vi, audio_url, created_at, updated_at) VALUES ((SELECT id FROM topics WHERE name = 'Office' LIMIT 1), 'deadline', '/ˈded.laɪn/', 'noun', 'Hạn chót, thời hạn hoàn thành công việc', 'All department managers must submit their annual budget proposals before the strict Friday deadline.', 'Tất cả trưởng các bộ phận phải nộp đề xuất ngân sách hàng năm trước hạn chót nghiêm ngặt vào thứ Sáu.', '/uploads/audio/deadline.wav', NOW(), NOW()) ON CONFLICT DO NOTHING;
INSERT INTO vocabularies (topic_id, word, phonetic, part_of_speech, meaning_vi, example_en, example_vi, audio_url, created_at, updated_at) VALUES ((SELECT id FROM topics WHERE name = 'Office' LIMIT 1), 'postpone', '/poʊˈspoʊn/', 'verb', 'hoãn lại, trì hoãn', 'The manager decided to postpone the quarterly budget meeting until all department heads arrive.', 'Trưởng phòng đã quyết định hoãn cuộc họp ngân sách hàng quý cho đến khi tất cả các trưởng bộ phận đến nơi.', '/uploads/audio/postpone.wav', NOW(), NOW()) ON CONFLICT DO NOTHING;
INSERT INTO vocabularies (topic_id, word, phonetic, part_of_speech, meaning_vi, example_en, example_vi, audio_url, created_at, updated_at) VALUES ((SELECT id FROM topics WHERE name = 'Office' LIMIT 1), 'reschedule', '/ˌriːˈskedʒ.uːl/', 'verb', 'dời lại lịch, sắp xếp lại lịch trình', 'Please notify the human resources manager if you need to reschedule your interview appointment.', 'Vui lòng thông báo cho quản lý nhân sự nếu bạn cần dời lại lịch hẹn phỏng vấn của mình.', '/uploads/audio/reschedule.wav', NOW(), NOW()) ON CONFLICT DO NOTHING;
INSERT INTO vocabularies (topic_id, word, phonetic, part_of_speech, meaning_vi, example_en, example_vi, audio_url, created_at, updated_at) VALUES ((SELECT id FROM topics WHERE name = 'Office' LIMIT 1), 'priority', '/praɪˈɔːrəti/', 'noun', 'sự ưu tiên, quyền ưu tiên', 'Completing the monthly financial report is our top priority before the board meeting.', 'Hoàn thành báo cáo tài chính hàng tháng là ưu tiên hàng đầu của chúng tôi trước cuộc họp hội đồng quản trị.', '/uploads/audio/priority.wav', NOW(), NOW()) ON CONFLICT DO NOTHING;
INSERT INTO vocabularies (topic_id, word, phonetic, part_of_speech, meaning_vi, example_en, example_vi, audio_url, created_at, updated_at) VALUES ((SELECT id FROM topics WHERE name = 'Office' LIMIT 1), 'workflow', '/ˈwɜːr.kfloʊ/', 'noun', 'quy trình làm việc', 'The new software significantly improves our office workflow by automating routine administrative tasks.', 'Phần mềm mới cải thiện đáng kể quy trình làm việc trong văn phòng của chúng tôi bằng cách tự động hóa các tác vụ hành chính thông thường.', '/uploads/audio/workflow.wav', NOW(), NOW()) ON CONFLICT DO NOTHING;
INSERT INTO vocabularies (topic_id, word, phonetic, part_of_speech, meaning_vi, example_en, example_vi, audio_url, created_at, updated_at) VALUES ((SELECT id FROM topics WHERE name = 'Office' LIMIT 1), 'procedure', '/prəˈsiː.dʒɚ/', 'noun', 'thủ tục, quy trình', 'All employees must follow the standard procedure for submitting their monthly expense reports.', 'Tất cả nhân viên phải tuân theo quy trình tiêu chuẩn để nộp báo cáo chi phí hàng tháng của họ.', '/uploads/audio/procedure.wav', NOW(), NOW()) ON CONFLICT DO NOTHING;
INSERT INTO vocabularies (topic_id, word, phonetic, part_of_speech, meaning_vi, example_en, example_vi, audio_url, created_at, updated_at) VALUES ((SELECT id FROM topics WHERE name = 'Office' LIMIT 1), 'paperwork', '/ˈpeɪ.pɚ.wɝːk/', 'noun', 'công việc giấy tờ, thủ tục hành chính', 'Please complete all the necessary paperwork before submitting your expense report to accounting.', 'Vui lòng hoàn thành tất cả các thủ tục giấy tờ cần thiết trước khi nộp báo cáo chi phí cho bộ phận kế toán.', '/uploads/audio/paperwork.wav', NOW(), NOW()) ON CONFLICT DO NOTHING;
INSERT INTO vocabularies (topic_id, word, phonetic, part_of_speech, meaning_vi, example_en, example_vi, audio_url, created_at, updated_at) VALUES ((SELECT id FROM topics WHERE name = 'Office' LIMIT 1), 'teleconference', '/ˈtel.əˌkɑːn.fɚ.əns/', 'noun', 'cuộc họp từ xa qua điện thoại hoặc video', 'All department managers are required to join the weekly teleconference scheduled for tomorrow morning.', 'Tất cả các trưởng phòng được yêu cầu tham gia cuộc họp từ xa hàng tuần được lên lịch vào sáng mai.', '/uploads/audio/teleconference.wav', NOW(), NOW()) ON CONFLICT DO NOTHING;
INSERT INTO vocabularies (topic_id, word, phonetic, part_of_speech, meaning_vi, example_en, example_vi, audio_url, created_at, updated_at) VALUES ((SELECT id FROM topics WHERE name = 'Personnel' LIMIT 1), 'recruit', '/rɪˈkruːt/', 'verb', 'tuyển dụng', 'The human resources department plans to recruit three new software engineers for the upcoming project.', 'Phòng nhân sự có kế hoạch tuyển dụng ba kỹ sư phần mềm mới cho dự án sắp tới.', '/uploads/audio/recruit.wav', NOW(), NOW()) ON CONFLICT DO NOTHING;
INSERT INTO vocabularies (topic_id, word, phonetic, part_of_speech, meaning_vi, example_en, example_vi, audio_url, created_at, updated_at) VALUES ((SELECT id FROM topics WHERE name = 'Personnel' LIMIT 1), 'hire', '/haɪər/', 'verb', 'thuê, tuyển dụng', 'The human resources department plans to hire three new software engineers before the end of next month.', 'Phòng nhân sự dự định tuyển dụng ba kỹ sư phần mềm mới trước khi kết thúc tháng tới.', '/uploads/audio/hire.wav', NOW(), NOW()) ON CONFLICT DO NOTHING;
INSERT INTO vocabularies (topic_id, word, phonetic, part_of_speech, meaning_vi, example_en, example_vi, audio_url, created_at, updated_at) VALUES ((SELECT id FROM topics WHERE name = 'Personnel' LIMIT 1), 'candidate', '/ˈkæn.dɪ.dət/', 'noun', 'ứng viên, thí sinh', 'The human resources manager interviewed three qualified candidates for the vacant accountant position yesterday.', 'Trưởng phòng nhân sự đã phỏng vấn ba ứng viên đủ điều kiện cho vị trí kế toán còn trống ngày hôm qua.', '/uploads/audio/candidate.wav', NOW(), NOW()) ON CONFLICT DO NOTHING;
INSERT INTO vocabularies (topic_id, word, phonetic, part_of_speech, meaning_vi, example_en, example_vi, audio_url, created_at, updated_at) VALUES ((SELECT id FROM topics WHERE name = 'Personnel' LIMIT 1), 'interview', '/ˈɪn.t̬ɚ.vjuː/', 'noun', 'cuộc phỏng vấn', 'The human resources manager scheduled a second interview with the top marketing candidate for tomorrow.', 'Trưởng phòng nhân sự đã lên lịch phỏng vấn vòng hai với ứng viên tiếp thị xuất sắc nhất vào ngày mai.', '/uploads/audio/interview.wav', NOW(), NOW()) ON CONFLICT DO NOTHING;
INSERT INTO vocabularies (topic_id, word, phonetic, part_of_speech, meaning_vi, example_en, example_vi, audio_url, created_at, updated_at) VALUES ((SELECT id FROM topics WHERE name = 'Personnel' LIMIT 1), 'qualification', '/ˌkwɑː.lə.fəˈkeɪ.ʃən/', 'noun', 'bằng cấp, chuyên môn, năng lực', 'All applicants must submit their relevant professional qualifications along with their resumes before Friday.', 'Tất cả ứng viên phải nộp các bằng cấp chuyên môn liên quan cùng với sơ yếu lý lịch trước thứ Sáu.', '/uploads/audio/qualification.wav', NOW(), NOW()) ON CONFLICT DO NOTHING;
INSERT INTO vocabularies (topic_id, word, phonetic, part_of_speech, meaning_vi, example_en, example_vi, audio_url, created_at, updated_at) VALUES ((SELECT id FROM topics WHERE name = 'Personnel' LIMIT 1), 'resume', '/rɪˈzuːm/', 'verb', 'tiếp tục, bắt đầu lại', 'The human resources department will resume the interview process for the marketing manager position tomorrow.', 'Bộ phận nhân sự sẽ tiếp tục quá trình phỏng vấn cho vị trí trưởng phòng marketing vào ngày mai.', '/uploads/audio/resume.wav', NOW(), NOW()) ON CONFLICT DO NOTHING;
INSERT INTO vocabularies (topic_id, word, phonetic, part_of_speech, meaning_vi, example_en, example_vi, audio_url, created_at, updated_at) VALUES ((SELECT id FROM topics WHERE name = 'Personnel' LIMIT 1), 'payroll', '/ˈpeɪ.roʊl/', 'noun', 'bảng lương, quỹ lương', 'The human resources department is currently processing the monthly payroll for all company employees.', 'Bộ phận nhân sự hiện đang xử lý bảng lương hàng tháng cho tất cả nhân viên công ty.', '/uploads/audio/payroll.wav', NOW(), NOW()) ON CONFLICT DO NOTHING;
INSERT INTO vocabularies (topic_id, word, phonetic, part_of_speech, meaning_vi, example_en, example_vi, audio_url, created_at, updated_at) VALUES ((SELECT id FROM topics WHERE name = 'Personnel' LIMIT 1), 'salary', '/ˈsæl.ɚ.i/', 'noun', 'tiền lương, mức lương', 'New employees will receive a competitive salary and comprehensive benefits package after the probation period.', 'Nhân viên mới sẽ nhận được mức lương cạnh tranh và gói phúc lợi toàn diện sau thời gian thử việc.', '/uploads/audio/salary.wav', NOW(), NOW()) ON CONFLICT DO NOTHING;
INSERT INTO vocabularies (topic_id, word, phonetic, part_of_speech, meaning_vi, example_en, example_vi, audio_url, created_at, updated_at) VALUES ((SELECT id FROM topics WHERE name = 'Personnel' LIMIT 1), 'bonus', '/ˈboʊ.nəs/', 'noun', 'tiền thưởng', 'All employees who exceeded their annual sales targets will receive a generous year-end bonus.', 'Tất cả nhân viên vượt chỉ tiêu bán hàng năm sẽ nhận được khoản tiền thưởng cuối năm hậu hĩnh.', '/uploads/audio/bonus.wav', NOW(), NOW()) ON CONFLICT DO NOTHING;
INSERT INTO vocabularies (topic_id, word, phonetic, part_of_speech, meaning_vi, example_en, example_vi, audio_url, created_at, updated_at) VALUES ((SELECT id FROM topics WHERE name = 'Personnel' LIMIT 1), 'benefit', '/ˈbɛn.ə.fɪt/', 'noun', 'phúc lợi, quyền lợi nhân viên', 'The human resources department announced an updated health insurance plan and additional retirement benefits for all full-time employees.', 'Phòng nhân sự đã thông báo về kế hoạch bảo hiểm y tế được cập nhật và các phúc lợi hưu trí bổ sung cho tất cả nhân viên toàn thời gian.', '/uploads/audio/benefit.wav', NOW(), NOW()) ON CONFLICT DO NOTHING;
INSERT INTO vocabularies (topic_id, word, phonetic, part_of_speech, meaning_vi, example_en, example_vi, audio_url, created_at, updated_at) VALUES ((SELECT id FROM topics WHERE name = 'Personnel' LIMIT 1), 'probation', '/proʊˈbeɪ.ʃən/', 'noun', 'thời gian thử việc', 'All newly hired software engineers must complete a three-month probation before receiving full employee benefits.', 'Tất cả kỹ sư phần mềm mới được tuyển dụng phải hoàn thành ba tháng thử việc trước khi nhận đầy đủ phúc lợi nhân viên.', '/uploads/audio/probation.wav', NOW(), NOW()) ON CONFLICT DO NOTHING;
INSERT INTO vocabularies (topic_id, word, phonetic, part_of_speech, meaning_vi, example_en, example_vi, audio_url, created_at, updated_at) VALUES ((SELECT id FROM topics WHERE name = 'Personnel' LIMIT 1), 'promotion', '/prəˈmoʊ.ʃən/', 'noun', 'sự thăng chức, việc thăng cấp', 'Ms. Davis received a well-deserved promotion to senior marketing manager after her successful product launch.', 'Bà Davis đã nhận được một đợt thăng chức xứng đáng lên làm quản lý tiếp thị cấp cao sau khi ra mắt sản phẩm thành công.', '/uploads/audio/promotion.wav', NOW(), NOW()) ON CONFLICT DO NOTHING;
INSERT INTO vocabularies (topic_id, word, phonetic, part_of_speech, meaning_vi, example_en, example_vi, audio_url, created_at, updated_at) VALUES ((SELECT id FROM topics WHERE name = 'Personnel' LIMIT 1), 'resign', '/rɪˈzaɪn/', 'verb', 'từ chức', 'Mr. Harrison decided to resign from his position as head of human resources.', 'Ông Harrison đã quyết định từ chức khỏi vị trí trưởng phòng nhân sự.', '/uploads/audio/resign.wav', NOW(), NOW()) ON CONFLICT DO NOTHING;
INSERT INTO vocabularies (topic_id, word, phonetic, part_of_speech, meaning_vi, example_en, example_vi, audio_url, created_at, updated_at) VALUES ((SELECT id FROM topics WHERE name = 'Personnel' LIMIT 1), 'retire', '/rɪˈtaɪr/', 'verb', 'về hưu', 'Mr. Harrison announced that he will retire from the company after thirty years of dedicated service.', 'Ông Harrison đã thông báo rằng ông sẽ về hưu khỏi công ty sau ba mươi năm cống hiến tận tụy.', '/uploads/audio/retire.wav', NOW(), NOW()) ON CONFLICT DO NOTHING;
INSERT INTO vocabularies (topic_id, word, phonetic, part_of_speech, meaning_vi, example_en, example_vi, audio_url, created_at, updated_at) VALUES ((SELECT id FROM topics WHERE name = 'Personnel' LIMIT 1), 'turnover', '/ˈtɝːnˌoʊ.vɚ/', 'noun', 'tỷ lệ nhân viên nghỉ việc, sự biến động nhân sự', 'The human resources department is implementing new retention strategies to reduce the high staff turnover.', 'Phòng nhân sự đang thực hiện các chiến lược giữ chân nhân viên mới để giảm tỷ lệ nghỉ việc cao.', '/uploads/audio/turnover.wav', NOW(), NOW()) ON CONFLICT DO NOTHING;
INSERT INTO vocabularies (topic_id, word, phonetic, part_of_speech, meaning_vi, example_en, example_vi, audio_url, created_at, updated_at) VALUES ((SELECT id FROM topics WHERE name = 'Personnel' LIMIT 1), 'performance', '/pərˈfɔːr.məns/', 'noun', 'hiệu suất làm việc, thành tích công tác', 'The manager reviewed each employee''s performance before deciding on the annual salary increases.', 'Người quản lý đã đánh giá hiệu suất làm việc của từng nhân viên trước khi quyết định tăng lương hàng năm.', '/uploads/audio/performance.wav', NOW(), NOW()) ON CONFLICT DO NOTHING;
INSERT INTO vocabularies (topic_id, word, phonetic, part_of_speech, meaning_vi, example_en, example_vi, audio_url, created_at, updated_at) VALUES ((SELECT id FROM topics WHERE name = 'Personnel' LIMIT 1), 'evaluate', '/ɪˈvæl.ju.eɪt/', 'verb', 'đánh giá', 'The manager will evaluate employee performance before deciding on the annual salary increases.', 'Trưởng phòng sẽ đánh giá hiệu suất làm việc của nhân viên trước khi quyết định tăng lương hàng năm.', '/uploads/audio/evaluate.wav', NOW(), NOW()) ON CONFLICT DO NOTHING;
INSERT INTO vocabularies (topic_id, word, phonetic, part_of_speech, meaning_vi, example_en, example_vi, audio_url, created_at, updated_at) VALUES ((SELECT id FROM topics WHERE name = 'Personnel' LIMIT 1), 'training', '/ˈtreɪ.nɪŋ/', 'noun', 'sự đào tạo, khóa tập huấn', 'All newly hired employees must complete safety training before working on the factory floor.', 'Tất cả nhân viên mới tuyển dụng phải hoàn thành khóa đào tạo an toàn trước khi làm việc tại xưởng sản xuất.', '/uploads/audio/training.wav', NOW(), NOW()) ON CONFLICT DO NOTHING;
INSERT INTO vocabularies (topic_id, word, phonetic, part_of_speech, meaning_vi, example_en, example_vi, audio_url, created_at, updated_at) VALUES ((SELECT id FROM topics WHERE name = 'Personnel' LIMIT 1), 'onboarding', '/ˈɑːnˌbɔːr.dɪŋ/', 'noun', 'quy trình hội nhập, tiếp nhận nhân viên mới', 'The human resources department designed a comprehensive onboarding program for all newly hired employees.', 'Bộ phận nhân sự đã thiết kế một chương trình hội nhập toàn diện cho tất cả nhân viên mới được tuyển dụng.', '/uploads/audio/onboarding.wav', NOW(), NOW()) ON CONFLICT DO NOTHING;
INSERT INTO vocabularies (topic_id, word, phonetic, part_of_speech, meaning_vi, example_en, example_vi, audio_url, created_at, updated_at) VALUES ((SELECT id FROM topics WHERE name = 'Personnel' LIMIT 1), 'pension', '/ˈpɛn.ʃən/', 'noun', 'lương hưu', 'Human resources will host a seminar explaining the new company pension plan for all retiring employees.', 'Phòng nhân sự sẽ tổ chức một buổi hội thảo giải thích kế hoạch lương hưu mới của công ty cho tất cả nhân viên sắp nghỉ hưu.', '/uploads/audio/pension.wav', NOW(), NOW()) ON CONFLICT DO NOTHING;
INSERT INTO vocabularies (topic_id, word, phonetic, part_of_speech, meaning_vi, example_en, example_vi, audio_url, created_at, updated_at) VALUES ((SELECT id FROM topics WHERE name = 'Personnel' LIMIT 1), 'overtime', '/ˈoʊ.vɚ.taɪm/', 'noun', 'thời gian làm thêm giờ, tiền làm thêm giờ', 'Employees who work overtime during the weekend will receive a higher hourly wage rate.', 'Nhân viên làm thêm giờ vào cuối tuần sẽ nhận được mức lương theo giờ cao hơn.', '/uploads/audio/overtime.wav', NOW(), NOW()) ON CONFLICT DO NOTHING;
INSERT INTO vocabularies (topic_id, word, phonetic, part_of_speech, meaning_vi, example_en, example_vi, audio_url, created_at, updated_at) VALUES ((SELECT id FROM topics WHERE name = 'Personnel' LIMIT 1), 'leave of absence', '/liːv əv ˈæb.əns/', 'noun', 'nghỉ phép, nghỉ việc tạm thời', 'Employees must submit a written request at least two weeks before taking a leave of absence.', 'Nhân viên phải nộp đơn xin nghỉ phép bằng văn bản ít nhất hai tuần trước khi nghỉ.', '/uploads/audio/leave_of_absence.wav', NOW(), NOW()) ON CONFLICT DO NOTHING;
INSERT INTO vocabularies (topic_id, word, phonetic, part_of_speech, meaning_vi, example_en, example_vi, audio_url, created_at, updated_at) VALUES ((SELECT id FROM topics WHERE name = 'Personnel' LIMIT 1), 'job opening', '/dʒɑːb ˈoʊ.pən.ɪŋ/', 'noun', 'vị trí tuyển dụng, cơ hội việc làm', 'The human resources department announced several new job openings in the marketing division today.', 'Phòng nhân sự đã thông báo một vài vị trí tuyển dụng mới trong bộ phận tiếp thị ngày hôm nay.', '/uploads/audio/job_opening.wav', NOW(), NOW()) ON CONFLICT DO NOTHING;
INSERT INTO vocabularies (topic_id, word, phonetic, part_of_speech, meaning_vi, example_en, example_vi, audio_url, created_at, updated_at) VALUES ((SELECT id FROM topics WHERE name = 'Personnel' LIMIT 1), 'headhunt', '/ˈhɛdˌhʌnt/', 'verb', 'săn đầu người, chiêu mộ nhân人才 cao cấp', 'The tech company decided to headhunt a senior marketing director from their main competitor.', 'Công ty công nghệ đã quyết định săn đầu người một giám đốc marketing cấp cao từ đối thủ chính của họ.', '/uploads/audio/headhunt.wav', NOW(), NOW()) ON CONFLICT DO NOTHING;
INSERT INTO vocabularies (topic_id, word, phonetic, part_of_speech, meaning_vi, example_en, example_vi, audio_url, created_at, updated_at) VALUES ((SELECT id FROM topics WHERE name = 'Personnel' LIMIT 1), 'reference', '/ˈref.ər.əns/', 'noun', 'thư giới thiệu, người giới thiệu', 'Please include three professional references in your application package before submitting it to human resources.', 'Vui lòng đính kèm ba thư giới thiệu chuyên môn trong hồ sơ ứng tuyển của bạn trước khi nộp cho bộ phận nhân sự.', '/uploads/audio/reference.wav', NOW(), NOW()) ON CONFLICT DO NOTHING;
INSERT INTO vocabularies (topic_id, word, phonetic, part_of_speech, meaning_vi, example_en, example_vi, audio_url, created_at, updated_at) VALUES ((SELECT id FROM topics WHERE name = 'Personnel' LIMIT 1), 'applicant', '/ˈæp.lə.kənt/', 'noun', 'người ứng tuyển, ứng viên', 'The human resources manager reviewed each applicant''s resume carefully before scheduling the final interviews.', 'Trưởng phòng nhân sự đã xem xét kỹ lưỡng sơ yếu lý lịch của từng ứng viên trước khi lên lịch phỏng vấn cuối cùng.', '/uploads/audio/applicant.wav', NOW(), NOW()) ON CONFLICT DO NOTHING;
INSERT INTO vocabularies (topic_id, word, phonetic, part_of_speech, meaning_vi, example_en, example_vi, audio_url, created_at, updated_at) VALUES ((SELECT id FROM topics WHERE name = 'Personnel' LIMIT 1), 'mentor', '/ˈmen.tɔːr/', 'noun', 'người hướng dẫn, người cố vấn', 'Experienced managers often act as a mentor to newly hired employees during their probationary period.', 'Các quản lý có kinh nghiệm thường đóng vai trò là người hướng dẫn cho các nhân viên mới tuyển dụng trong thời gian thử việc.', '/uploads/audio/mentor.wav', NOW(), NOW()) ON CONFLICT DO NOTHING;
INSERT INTO vocabularies (topic_id, word, phonetic, part_of_speech, meaning_vi, example_en, example_vi, audio_url, created_at, updated_at) VALUES ((SELECT id FROM topics WHERE name = 'Personnel' LIMIT 1), 'staffing', '/ˈstæf.ɪŋ/', 'noun', 'Sự bố trí nhân sự, việc cung cấp nhân lực', 'The human resources department is currently reviewing our staffing levels to prepare for the upcoming busy season.', 'Phòng nhân sự hiện đang xem xét lại mức độ bố trí nhân sự của chúng ta để chuẩn bị cho mùa cao điểm sắp tới.', '/uploads/audio/staffing.wav', NOW(), NOW()) ON CONFLICT DO NOTHING;
INSERT INTO vocabularies (topic_id, word, phonetic, part_of_speech, meaning_vi, example_en, example_vi, audio_url, created_at, updated_at) VALUES ((SELECT id FROM topics WHERE name = 'Personnel' LIMIT 1), 'dismiss', '/dɪsˈmɪs/', 'verb', 'sa thải, sa thải nhân viên', 'The manager decided to dismiss the employee due to repeated absences and poor performance.', 'Người quản lý đã quyết định sa thải nhân viên do nghỉ làm nhiều lần và hiệu suất kém.', '/uploads/audio/dismiss.wav', NOW(), NOW()) ON CONFLICT DO NOTHING;
INSERT INTO vocabularies (topic_id, word, phonetic, part_of_speech, meaning_vi, example_en, example_vi, audio_url, created_at, updated_at) VALUES ((SELECT id FROM topics WHERE name = 'Personnel' LIMIT 1), 'appraisal', '/əˈpreɪ.zəl/', 'noun', 'sự đánh giá, sự thẩm định (nhân viên, hiệu suất làm việc)', 'All department managers must submit their annual performance appraisal reports by Friday afternoon.', 'Tất cả trưởng bộ phận phải nộp báo cáo đánh giá hiệu suất hàng năm trước chiều thứ Sáu.', '/uploads/audio/appraisal.wav', NOW(), NOW()) ON CONFLICT DO NOTHING;
INSERT INTO vocabularies (topic_id, word, phonetic, part_of_speech, meaning_vi, example_en, example_vi, audio_url, created_at, updated_at) VALUES ((SELECT id FROM topics WHERE name = 'Shopping' LIMIT 1), 'inventory', '/ˈɪn.vən.tɔːr.i/', 'noun', 'hàng tồn kho, danh mục hàng hóa', 'The boutique manager reviewed the new inventory to ensure all clothing items were properly tagged.', 'Người quản lý cửa hàng thời trang đã xem xét hàng tồn kho mới để đảm bảo tất cả các mặt hàng quần áo được dán nhãn đúng cách.', '/uploads/audio/inventory.wav', NOW(), NOW()) ON CONFLICT DO NOTHING;
INSERT INTO vocabularies (topic_id, word, phonetic, part_of_speech, meaning_vi, example_en, example_vi, audio_url, created_at, updated_at) VALUES ((SELECT id FROM topics WHERE name = 'Shopping' LIMIT 1), 'warehouse', '/ˈwer.haʊs/', 'noun', 'kho hàng, nhà kho', 'The newly ordered merchandise will be delivered directly from the central warehouse to the retail store.', 'Số hàng hóa mới đặt sẽ được giao trực tiếp từ kho trung tâm đến cửa hàng bán lẻ.', '/uploads/audio/warehouse.wav', NOW(), NOW()) ON CONFLICT DO NOTHING;
INSERT INTO vocabularies (topic_id, word, phonetic, part_of_speech, meaning_vi, example_en, example_vi, audio_url, created_at, updated_at) VALUES ((SELECT id FROM topics WHERE name = 'Shopping' LIMIT 1), 'supplier', '/səˈplaɪ.ɚ/', 'noun', 'nhà cung cấp', 'Our purchasing department is currently negotiating a bulk discount with the new office furniture supplier.', 'Phòng mua hàng của chúng tôi hiện đang đàm phán mức chiết khấu số lượng lớn với nhà cung cấp nội thất văn phòng mới.', '/uploads/audio/supplier.wav', NOW(), NOW()) ON CONFLICT DO NOTHING;
INSERT INTO vocabularies (topic_id, word, phonetic, part_of_speech, meaning_vi, example_en, example_vi, audio_url, created_at, updated_at) VALUES ((SELECT id FROM topics WHERE name = 'Shopping' LIMIT 1), 'vendor', '/ˈvɛn.dər/', 'noun', 'nhà cung cấp, người bán hàng', 'Our purchasing department is currently negotiating contract terms with a new office supply vendor.', 'Bộ phận mua hàng của chúng tôi hiện đang đàm phán các điều khoản hợp đồng với một nhà cung cấp văn phòng phẩm mới.', '/uploads/audio/vendor.wav', NOW(), NOW()) ON CONFLICT DO NOTHING;
INSERT INTO vocabularies (topic_id, word, phonetic, part_of_speech, meaning_vi, example_en, example_vi, audio_url, created_at, updated_at) VALUES ((SELECT id FROM topics WHERE name = 'Shopping' LIMIT 1), 'distributor', '/dɪˈstrɪb.jə.tər/', 'noun', 'nhà phân phối, đại lý phân phối', 'Our boutique signed an exclusive contract with the new cosmetics distributor in downtown.', 'Cửa hàng thời trang của chúng tôi đã ký hợp đồng độc quyền với nhà phân phối mỹ phẩm mới ở trung tâm thành phố.', '/uploads/audio/distributor.wav', NOW(), NOW()) ON CONFLICT DO NOTHING;
INSERT INTO vocabularies (topic_id, word, phonetic, part_of_speech, meaning_vi, example_en, example_vi, audio_url, created_at, updated_at) VALUES ((SELECT id FROM topics WHERE name = 'Shopping' LIMIT 1), 'wholesale', '/ˈhoʊl.seɪl/', 'adjective', 'bán sỉ, bán buôn', 'Our boutique purchases clothing items at wholesale prices to maximize profit margins for the season.', 'Cửa hàng thời trang của chúng tôi mua các mặt hàng quần áo với giá bán sỉ để tối đa hóa lợi nhuận cho mùa này.', '/uploads/audio/wholesale.wav', NOW(), NOW()) ON CONFLICT DO NOTHING;
INSERT INTO vocabularies (topic_id, word, phonetic, part_of_speech, meaning_vi, example_en, example_vi, audio_url, created_at, updated_at) VALUES ((SELECT id FROM topics WHERE name = 'Shopping' LIMIT 1), 'retail', '/ˈriː.teɪl/', 'noun', 'bán lẻ', 'Our company plans to expand its retail operations into international markets by next year.', 'Công ty chúng tôi có kế hoạch mở rộng hoạt động bán lẻ sang các thị trường quốc tế vào năm tới.', '/uploads/audio/retail.wav', NOW(), NOW()) ON CONFLICT DO NOTHING;
INSERT INTO vocabularies (topic_id, word, phonetic, part_of_speech, meaning_vi, example_en, example_vi, audio_url, created_at, updated_at) VALUES ((SELECT id FROM topics WHERE name = 'Shopping' LIMIT 1), 'order', '/ˈɔːr.dər/', 'verb', 'đặt hàng', 'Customers can easily order items online and choose home delivery during the promotional period.', 'Khách hàng có thể dễ dàng đặt hàng trực tuyến và chọn giao hàng tận nhà trong thời gian khuyến mãi.', '/uploads/audio/order.wav', NOW(), NOW()) ON CONFLICT DO NOTHING;
INSERT INTO vocabularies (topic_id, word, phonetic, part_of_speech, meaning_vi, example_en, example_vi, audio_url, created_at, updated_at) VALUES ((SELECT id FROM topics WHERE name = 'Shopping' LIMIT 1), 'shipment', '/ˈʃɪp.mənt/', 'noun', 'lô hàng, sự vận chuyển hàng hóa', 'Please inspect the latest online shopping shipment immediately upon delivery to ensure no items are damaged.', 'Vui lòng kiểm tra lô hàng mua sắm trực tuyến mới nhất ngay khi giao hàng để đảm bảo không có mặt hàng nào bị hư hỏng.', '/uploads/audio/shipment.wav', NOW(), NOW()) ON CONFLICT DO NOTHING;
INSERT INTO vocabularies (topic_id, word, phonetic, part_of_speech, meaning_vi, example_en, example_vi, audio_url, created_at, updated_at) VALUES ((SELECT id FROM topics WHERE name = 'Shopping' LIMIT 1), 'tracking', '/ˈtræk.ɪŋ/', 'noun', 'sự theo dõi, việc dò tìm (đơn hàng, bưu phẩm)', 'You can check the online tracking system to monitor the delivery status of your purchased items.', 'Bạn có thể kiểm tra hệ thống theo dõi trực tuyến để giám sát tình trạng giao hàng của các mặt hàng đã mua.', '/uploads/audio/tracking.wav', NOW(), NOW()) ON CONFLICT DO NOTHING;
INSERT INTO vocabularies (topic_id, word, phonetic, part_of_speech, meaning_vi, example_en, example_vi, audio_url, created_at, updated_at) VALUES ((SELECT id FROM topics WHERE name = 'Shopping' LIMIT 1), 'courier', '/ˈkʊr.i.ɚ/', 'noun', 'nhân viên chuyển phát, công ty chuyển phát', 'Please send the signed shopping agreement back to our main office via an express courier.', 'Vui lòng gửi lại thỏa thuận mua sắm đã ký về văn phòng chính của chúng tôi thông qua dịch vụ chuyển phát nhanh.', '/uploads/audio/courier.wav', NOW(), NOW()) ON CONFLICT DO NOTHING;
INSERT INTO vocabularies (topic_id, word, phonetic, part_of_speech, meaning_vi, example_en, example_vi, audio_url, created_at, updated_at) VALUES ((SELECT id FROM topics WHERE name = 'Shopping' LIMIT 1), 'freight', '/freɪt/', 'noun', 'hàng hóa, cước vận chuyển', 'The department store arranged for the bulk merchandise freight to be delivered by Friday.', 'Cửa hàng bách hóa đã sắp xếp để lô hàng hóa số lượng lớn được giao trước thứ Sáu.', '/uploads/audio/freight.wav', NOW(), NOW()) ON CONFLICT DO NOTHING;
INSERT INTO vocabularies (topic_id, word, phonetic, part_of_speech, meaning_vi, example_en, example_vi, audio_url, created_at, updated_at) VALUES ((SELECT id FROM topics WHERE name = 'Shopping' LIMIT 1), 'package', '/ˈpæk.ɪdʒ/', 'noun', 'bưu kiện, gói hàng', 'Please ensure your shopping package is securely sealed before returning it to the store.', 'Vui lòng đảm bảo bưu kiện mua sắm của bạn được niêm phong chắc chắn trước khi trả lại cửa hàng.', '/uploads/audio/package.wav', NOW(), NOW()) ON CONFLICT DO NOTHING;
INSERT INTO vocabularies (topic_id, word, phonetic, part_of_speech, meaning_vi, example_en, example_vi, audio_url, created_at, updated_at) VALUES ((SELECT id FROM topics WHERE name = 'Shopping' LIMIT 1), 'parcel', '/ˈpɑːr.səl/', 'noun', 'bưu kiện, gói hàng', 'Customers can track their online shopping parcel using the tracking number provided in the confirmation email.', 'Khách hàng có thể theo dõi bưu kiện mua sắm trực tuyến của họ bằng mã theo dõi được cung cấp trong email xác nhận.', '/uploads/audio/parcel.wav', NOW(), NOW()) ON CONFLICT DO NOTHING;
INSERT INTO vocabularies (topic_id, word, phonetic, part_of_speech, meaning_vi, example_en, example_vi, audio_url, created_at, updated_at) VALUES ((SELECT id FROM topics WHERE name = 'Shopping' LIMIT 1), 'dispatch', '/dɪˈspætʃ/', 'verb', 'gửi đi, giải quyết', 'We will dispatch your online shopping order within twenty-four hours of payment confirmation.', 'Chúng tôi sẽ gửi đơn hàng mua sắm trực tuyến của bạn trong vòng 24 giờ kể từ khi xác nhận thanh toán.', '/uploads/audio/dispatch.wav', NOW(), NOW()) ON CONFLICT DO NOTHING;
INSERT INTO vocabularies (topic_id, word, phonetic, part_of_speech, meaning_vi, example_en, example_vi, audio_url, created_at, updated_at) VALUES ((SELECT id FROM topics WHERE name = 'Shopping' LIMIT 1), 'in transit', '/ɪn ˈtræn.zɪt/', 'prepositional phrase', 'đang được vận chuyển, đang trên đường giao hàng', 'Please ensure all merchandise is fully insured while it remains in transit to our warehouse.', 'Vui lòng đảm bảo tất cả hàng hóa được bảo hiểm đầy đủ khi vẫn đang trên đường chuyển đến kho của chúng tôi.', '/uploads/audio/in_transit.wav', NOW(), NOW()) ON CONFLICT DO NOTHING;
INSERT INTO vocabularies (topic_id, word, phonetic, part_of_speech, meaning_vi, example_en, example_vi, audio_url, created_at, updated_at) VALUES ((SELECT id FROM topics WHERE name = 'Shopping' LIMIT 1), 'return policy', '/rɪˈtɝːn ˈpɑː.lə.si/', 'noun', 'chính sách đổi trả hàng', 'Please read our return policy carefully before purchasing any electronic items from this retail store.', 'Vui lòng đọc kỹ chính sách đổi trả hàng của chúng tôi trước khi mua bất kỳ mặt hàng điện tử nào từ cửa hàng bán lẻ này.', '/uploads/audio/return_policy.wav', NOW(), NOW()) ON CONFLICT DO NOTHING;
INSERT INTO vocabularies (topic_id, word, phonetic, part_of_speech, meaning_vi, example_en, example_vi, audio_url, created_at, updated_at) VALUES ((SELECT id FROM topics WHERE name = 'Shopping' LIMIT 1), 'refund', '/ˈriː.fʌnd/', 'noun', 'tiền hoàn lại', 'Customers can request a full refund within thirty days of purchase with a valid receipt.', 'Khách hàng có thể yêu cầu hoàn lại toàn bộ tiền trong vòng ba mươi ngày kể từ khi mua hàng kèm theo biên lai hợp lệ.', '/uploads/audio/refund.wav', NOW(), NOW()) ON CONFLICT DO NOTHING;
INSERT INTO vocabularies (topic_id, word, phonetic, part_of_speech, meaning_vi, example_en, example_vi, audio_url, created_at, updated_at) VALUES ((SELECT id FROM topics WHERE name = 'Shopping' LIMIT 1), 'exchange', '/ɪksˈtʃeɪndʒ/', 'verb', 'đổi, đổi trả hàng hóa', 'Customers can easily exchange purchased items within thirty days with a valid receipt.', 'Khách hàng có thể dễ dàng đổi các mặt hàng đã mua trong vòng ba mươi ngày với hóa đơn hợp lệ.', '/uploads/audio/exchange.wav', NOW(), NOW()) ON CONFLICT DO NOTHING;
INSERT INTO vocabularies (topic_id, word, phonetic, part_of_speech, meaning_vi, example_en, example_vi, audio_url, created_at, updated_at) VALUES ((SELECT id FROM topics WHERE name = 'Shopping' LIMIT 1), 'warranty', '/ˈwɔːr.ən.ti/', 'noun', 'bảo hành', 'Please retain your receipt as proof of purchase to validate the product warranty.', 'Vui lòng giữ lại biên lai mua hàng như bằng chứng để có hiệu lực bảo hành sản phẩm.', '/uploads/audio/warranty.wav', NOW(), NOW()) ON CONFLICT DO NOTHING;
INSERT INTO vocabularies (topic_id, word, phonetic, part_of_speech, meaning_vi, example_en, example_vi, audio_url, created_at, updated_at) VALUES ((SELECT id FROM topics WHERE name = 'Shopping' LIMIT 1), 'bulk', '/bʌlk/', 'noun', 'số lượng lớn, hàng sỉ', 'Customers who purchase office supplies in bulk will receive a special discount on their total order.', 'Khách hàng mua văn phòng phẩm số lượng lớn sẽ nhận được chiết khấu đặc biệt cho tổng đơn hàng của họ.', '/uploads/audio/bulk.wav', NOW(), NOW()) ON CONFLICT DO NOTHING;
INSERT INTO vocabularies (topic_id, word, phonetic, part_of_speech, meaning_vi, example_en, example_vi, audio_url, created_at, updated_at) VALUES ((SELECT id FROM topics WHERE name = 'Shopping' LIMIT 1), 'discount', '/ˈdɪs.kaʊnt/', 'noun', 'sự giảm giá, chiết khấu', 'Customers who sign up for our loyalty program will receive a special discount on all purchases.', 'Khách hàng đăng ký chương trình khách hàng thân thiết của chúng tôi sẽ nhận được mức giảm giá đặc biệt cho mọi giao dịch mua sắm.', '/uploads/audio/discount.wav', NOW(), NOW()) ON CONFLICT DO NOTHING;
INSERT INTO vocabularies (topic_id, word, phonetic, part_of_speech, meaning_vi, example_en, example_vi, audio_url, created_at, updated_at) VALUES ((SELECT id FROM topics WHERE name = 'Shopping' LIMIT 1), 'clearance', '/ˈklɪr.əns/', 'noun', 'sự thanh lý hàng hóa, bán giảm giá', 'The department store is offering deep discounts on all winter clothing during this weekend clearance.', 'Cửa hàng bách hóa đang giảm giá sâu cho tất cả quần áo mùa đông trong đợt thanh lý cuối tuần này.', '/uploads/audio/clearance.wav', NOW(), NOW()) ON CONFLICT DO NOTHING;
INSERT INTO vocabularies (topic_id, word, phonetic, part_of_speech, meaning_vi, example_en, example_vi, audio_url, created_at, updated_at) VALUES ((SELECT id FROM topics WHERE name = 'Shopping' LIMIT 1), 'rebate', '/ˈriː.beɪt/', 'noun', 'tiền hoàn lại, sự giảm giá', 'Customers who purchase the new laptop model this week are eligible for a fifty-dollar mail-in rebate.', 'Khách hàng mua mẫu máy tính xách tay mới trong tuần này đủ điều kiện nhận khoản tiền hoàn lại qua đường bưu điện trị giá năm mươi đô la.', '/uploads/audio/rebate.wav', NOW(), NOW()) ON CONFLICT DO NOTHING;
INSERT INTO vocabularies (topic_id, word, phonetic, part_of_speech, meaning_vi, example_en, example_vi, audio_url, created_at, updated_at) VALUES ((SELECT id FROM topics WHERE name = 'Shopping' LIMIT 1), 'voucher', '/ˈvaʊ.tʃɚ/', 'noun', 'phiếu mua hàng, phiếu giảm giá', 'Customers will receive a twenty-dollar shopping voucher after spending over one hundred dollars today.', 'Khách hàng sẽ nhận được một phiếu mua hàng trị giá 20 đô la sau khi chi tiêu trên 100 đô la ngày hôm nay.', '/uploads/audio/voucher.wav', NOW(), NOW()) ON CONFLICT DO NOTHING;
INSERT INTO vocabularies (topic_id, word, phonetic, part_of_speech, meaning_vi, example_en, example_vi, audio_url, created_at, updated_at) VALUES ((SELECT id FROM topics WHERE name = 'Shopping' LIMIT 1), 'checkout', '/ˈtʃɛk.aʊt/', 'noun', 'quầy thanh toán', 'Please place your items on the conveyor belt at the checkout to speed up the process.', 'Vui lòng đặt các mặt hàng của bạn lên băng chuyên tại quầy thanh toán để đẩy nhanh quá trình.', '/uploads/audio/checkout.wav', NOW(), NOW()) ON CONFLICT DO NOTHING;
INSERT INTO vocabularies (topic_id, word, phonetic, part_of_speech, meaning_vi, example_en, example_vi, audio_url, created_at, updated_at) VALUES ((SELECT id FROM topics WHERE name = 'Shopping' LIMIT 1), 'merchandise', '/ˈmɜːr.tʃən.daɪz/', 'noun', 'hàng hóa', 'Customers can return damaged merchandise within thirty days with a valid purchase receipt.', 'Khách hàng có thể đổi trả hàng hóa bị hỏng trong vòng ba mươi ngày với biên lai mua hàng hợp lệ.', '/uploads/audio/merchandise.wav', NOW(), NOW()) ON CONFLICT DO NOTHING;
INSERT INTO vocabularies (topic_id, word, phonetic, part_of_speech, meaning_vi, example_en, example_vi, audio_url, created_at, updated_at) VALUES ((SELECT id FROM topics WHERE name = 'Shopping' LIMIT 1), 'restock', '/riˈstɑːk/', 'verb', 'bổ sung hàng hóa, nhập thêm hàng mới', 'The supermarket manager decided to restock the empty shelves before the weekend shoppers arrive.', 'Người quản lý siêu thị quyết định bổ sung hàng lên các kệ trống trước khi khách mua sắm cuối tuần đến.', '/uploads/audio/restock.wav', NOW(), NOW()) ON CONFLICT DO NOTHING;
INSERT INTO vocabularies (topic_id, word, phonetic, part_of_speech, meaning_vi, example_en, example_vi, audio_url, created_at, updated_at) VALUES ((SELECT id FROM topics WHERE name = 'Shopping' LIMIT 1), 'defect', '/ˈdiː.fekt/', 'noun', 'lỗi, khiếm khuyết, khuyết tật sản phẩm', 'Customers who discover a defect in their purchased items can request a full refund.', 'Khách hàng phát hiện lỗi ở mặt hàng đã mua có thể yêu cầu hoàn lại tiền đầy đủ.', '/uploads/audio/defect.wav', NOW(), NOW()) ON CONFLICT DO NOTHING;
INSERT INTO vocabularies (topic_id, word, phonetic, part_of_speech, meaning_vi, example_en, example_vi, audio_url, created_at, updated_at) VALUES ((SELECT id FROM topics WHERE name = 'Travel' LIMIT 1), 'itinerary', '/aɪˈtɪn.ə.rer.i/', 'noun', 'lịch trình chuyến đi', 'Please review the detailed travel itinerary and confirm your flight details by Friday afternoon.', 'Vui lòng xem lại lịch trình chuyến đi chi tiết và xác nhận thông tin chuyến bay của bạn trước trưa thứ Sáu.', '/uploads/audio/itinerary.wav', NOW(), NOW()) ON CONFLICT DO NOTHING;
INSERT INTO vocabularies (topic_id, word, phonetic, part_of_speech, meaning_vi, example_en, example_vi, audio_url, created_at, updated_at) VALUES ((SELECT id FROM topics WHERE name = 'Travel' LIMIT 1), 'boarding pass', '/ˈbɔːr.dɪŋ ˌpæs/', 'noun', 'thẻ lên máy bay', 'Passengers must present their valid boarding pass and a photo ID at the departure gate.', 'Hành khách phải xuất trình thẻ lên máy bay hợp lệ và giấy tờ tùy thân có ảnh tại cửa khởi hành.', '/uploads/audio/boarding_pass.wav', NOW(), NOW()) ON CONFLICT DO NOTHING;
INSERT INTO vocabularies (topic_id, word, phonetic, part_of_speech, meaning_vi, example_en, example_vi, audio_url, created_at, updated_at) VALUES ((SELECT id FROM topics WHERE name = 'Travel' LIMIT 1), 'reservation', '/ˌrɛz.ərˈveɪ.ʃən/', 'noun', 'sự đặt chỗ, sự đặt trước', 'Please confirm your hotel reservation at least three days before your upcoming business trip.', 'Vui lòng xác nhận việc đặt phòng khách sạn của bạn ít nhất ba ngày trước chuyến công tác sắp tới.', '/uploads/audio/reservation.wav', NOW(), NOW()) ON CONFLICT DO NOTHING;
INSERT INTO vocabularies (topic_id, word, phonetic, part_of_speech, meaning_vi, example_en, example_vi, audio_url, created_at, updated_at) VALUES ((SELECT id FROM topics WHERE name = 'Travel' LIMIT 1), 'delay', '/dɪˈleɪ/', 'verb', 'sự chậm trễ, hoãn lại', 'Bad weather conditions in the region will inevitably delay several international flights today.', 'Điều kiện thời tiết xấu trong khu vực chắc chắn sẽ làm hoãn một số chuyến bay quốc tế ngày hôm nay.', '/uploads/audio/delay.wav', NOW(), NOW()) ON CONFLICT DO NOTHING;
INSERT INTO vocabularies (topic_id, word, phonetic, part_of_speech, meaning_vi, example_en, example_vi, audio_url, created_at, updated_at) VALUES ((SELECT id FROM topics WHERE name = 'Travel' LIMIT 1), 'cancel', '/ˈkæn.səl/', 'verb', 'hủy bỏ', 'Passengers are advised to check their flight status before heading to the airport in case airlines cancel.', 'Hành khách được khuyên nên kiểm tra tình trạng chuyến bay trước khi ra sân bay trong trường hợp các hãng hàng không hủy chuyến.', '/uploads/audio/cancel.wav', NOW(), NOW()) ON CONFLICT DO NOTHING;
INSERT INTO vocabularies (topic_id, word, phonetic, part_of_speech, meaning_vi, example_en, example_vi, audio_url, created_at, updated_at) VALUES ((SELECT id FROM topics WHERE name = 'Travel' LIMIT 1), 'baggage', '/ˈbæɡ.ɪdʒ/', 'noun', 'hành lý', 'All passengers must collect their checked baggage from carousel three upon arrival at the destination airport.', 'Tất cả hành khách phải nhận hành lý ký gửi của họ tại băng chuyền số ba khi đến sân bay điểm đến.', '/uploads/audio/baggage.wav', NOW(), NOW()) ON CONFLICT DO NOTHING;
INSERT INTO vocabularies (topic_id, word, phonetic, part_of_speech, meaning_vi, example_en, example_vi, audio_url, created_at, updated_at) VALUES ((SELECT id FROM topics WHERE name = 'Travel' LIMIT 1), 'luggage', '/ˈlʌɡɪdʒ/', 'noun', 'hành lý', 'All passengers must clearly label their luggage before checking in at the airport counter.', 'Tất cả hành khách phải dán nhãn rõ ràng lên hành lý của họ trước khi làm thủ tục tại quầy sân bay.', '/uploads/audio/luggage.wav', NOW(), NOW()) ON CONFLICT DO NOTHING;
INSERT INTO vocabularies (topic_id, word, phonetic, part_of_speech, meaning_vi, example_en, example_vi, audio_url, created_at, updated_at) VALUES ((SELECT id FROM topics WHERE name = 'Travel' LIMIT 1), 'customs', '/ˈkʌs.təmz/', 'noun', 'thủ tục hải quan', 'All international passengers must complete their declaration forms before passing through customs at the arrival airport.', 'Tất cả hành khách quốc tế phải điền tờ khai trước khi qua thủ tục hải quan tại sân bay đến.', '/uploads/audio/customs.wav', NOW(), NOW()) ON CONFLICT DO NOTHING;
INSERT INTO vocabularies (topic_id, word, phonetic, part_of_speech, meaning_vi, example_en, example_vi, audio_url, created_at, updated_at) VALUES ((SELECT id FROM topics WHERE name = 'Travel' LIMIT 1), 'currency exchange', '/ˈkɜː.rən.si ɪsˈtʃeɪndʒ/', 'noun', 'quầy đổi ngoại tệ, dịch vụ đổi tiền', 'Travelers can use the airport currency exchange service to get local cash before leaving.', 'Du khách có thể sử dụng dịch vụ đổi ngoại tệ tại sân bay để lấy tiền mặt địa phương trước khi khởi hành.', '/uploads/audio/currency_exchange.wav', NOW(), NOW()) ON CONFLICT DO NOTHING;
INSERT INTO vocabularies (topic_id, word, phonetic, part_of_speech, meaning_vi, example_en, example_vi, audio_url, created_at, updated_at) VALUES ((SELECT id FROM topics WHERE name = 'Travel' LIMIT 1), 'shuttle', '/ˈʃʌt.əl/', 'noun', 'xe đưa đón', 'The hotel provides a complimentary shuttle to transport guests directly to the airport terminal.', 'Khách sạn cung cấp dịch vụ xe đưa đón miễn phí để chở khách trực tiếp đến nhà ga sân bay.', '/uploads/audio/shuttle.wav', NOW(), NOW()) ON CONFLICT DO NOTHING;
INSERT INTO vocabularies (topic_id, word, phonetic, part_of_speech, meaning_vi, example_en, example_vi, audio_url, created_at, updated_at) VALUES ((SELECT id FROM topics WHERE name = 'Travel' LIMIT 1), 'rental car', '/ˈren.təl kɑːr/', 'noun', 'xe hơi cho thuê', 'Please remember to reserve a rental car before your upcoming business trip to Chicago.', 'Hãy nhớ đặt một chiếc xe hơi cho thuê trước chuyến công tác sắp tới của bạn đến Chicago.', '/uploads/audio/rental_car.wav', NOW(), NOW()) ON CONFLICT DO NOTHING;
INSERT INTO vocabularies (topic_id, word, phonetic, part_of_speech, meaning_vi, example_en, example_vi, audio_url, created_at, updated_at) VALUES ((SELECT id FROM topics WHERE name = 'Travel' LIMIT 1), 'departure', '/dɪˈpɑːr.tʃər/', 'noun', 'sự khởi hành, chuyến bay đi', 'All passengers must check their gate numbers at least thirty minutes before their scheduled flight departure.', 'Tất cả hành khách phải kiểm tra số cổng của họ ít nhất ba mươi phút trước giờ khởi hành chuyến bay.', '/uploads/audio/departure.wav', NOW(), NOW()) ON CONFLICT DO NOTHING;
INSERT INTO vocabularies (topic_id, word, phonetic, part_of_speech, meaning_vi, example_en, example_vi, audio_url, created_at, updated_at) VALUES ((SELECT id FROM topics WHERE name = 'Travel' LIMIT 1), 'arrival', '/əˈraɪ.vəl/', 'noun', 'sự đến, sự tới nơi', 'All passengers are requested to remain seated until the aircraft comes to a complete arrival.', 'Tất cả hành khách được yêu cầu ngồi yên cho đến khi máy bay đến nơi hoàn toàn.', '/uploads/audio/arrival.wav', NOW(), NOW()) ON CONFLICT DO NOTHING;
INSERT INTO vocabularies (topic_id, word, phonetic, part_of_speech, meaning_vi, example_en, example_vi, audio_url, created_at, updated_at) VALUES ((SELECT id FROM topics WHERE name = 'Travel' LIMIT 1), 'commute', '/kəˈmjuːt/', 'verb', 'đi lại giữa nhà và nơi làm việc', 'Many business travelers prefer to commute by high-speed train to avoid heavy morning traffic congestion.', 'Nhiều khách du lịch công tác thích đi lại bằng tàu cao tốc để tránh tình trạng tắc nghẽn giao thông buổi sáng.', '/uploads/audio/commute.wav', NOW(), NOW()) ON CONFLICT DO NOTHING;
INSERT INTO vocabularies (topic_id, word, phonetic, part_of_speech, meaning_vi, example_en, example_vi, audio_url, created_at, updated_at) VALUES ((SELECT id FROM topics WHERE name = 'Travel' LIMIT 1), 'transit', '/ˈtræn.zɪt/', 'noun', 'sự quá cảnh, sự vận chuyển', 'All luggage must remain securely tagged throughout the entire international flight transit process.', 'Tất cả hành lý phải được gắn thẻ an toàn trong toàn bộ quá trình quá cảnh chuyến bay quốc tế.', '/uploads/audio/transit.wav', NOW(), NOW()) ON CONFLICT DO NOTHING;
INSERT INTO vocabularies (topic_id, word, phonetic, part_of_speech, meaning_vi, example_en, example_vi, audio_url, created_at, updated_at) VALUES ((SELECT id FROM topics WHERE name = 'Travel' LIMIT 1), 'connecting flight', '/kəˈnek.ɪŋ flaɪt/', 'noun', 'chuyến bay nối chuyến', 'Passengers traveling to the international conference must book a connecting flight through the main hub.', 'Hành khách đi dự hội nghị quốc tế phải đặt một chuyến bay nối chuyến qua trung tâm chính.', '/uploads/audio/connecting_flight.wav', NOW(), NOW()) ON CONFLICT DO NOTHING;
INSERT INTO vocabularies (topic_id, word, phonetic, part_of_speech, meaning_vi, example_en, example_vi, audio_url, created_at, updated_at) VALUES ((SELECT id FROM topics WHERE name = 'Travel' LIMIT 1), 'layover', '/ˈleɪˌoʊ.vɚ/', 'noun', 'sự dừng chân, thời gian quá cảnh', 'Passengers experiencing a long layover at the international airport are offered free city tours.', 'Hành khách trải qua thời gian quá cảnh dài tại sân bay quốc tế được cung cấp các chuyến tham quan thành phố miễn phí.', '/uploads/audio/layover.wav', NOW(), NOW()) ON CONFLICT DO NOTHING;
INSERT INTO vocabularies (topic_id, word, phonetic, part_of_speech, meaning_vi, example_en, example_vi, audio_url, created_at, updated_at) VALUES ((SELECT id FROM topics WHERE name = 'Travel' LIMIT 1), 'fare', '/fɛr/', 'noun', 'tiền vé (tàu, xe, máy bay)', 'Passengers must purchase their train tickets in advance to secure the discounted travel fare.', 'Hành khách phải mua vé tàu trước để đảm bảo nhận được mức giá vé đi lại đã giảm.', '/uploads/audio/fare.wav', NOW(), NOW()) ON CONFLICT DO NOTHING;
INSERT INTO vocabularies (topic_id, word, phonetic, part_of_speech, meaning_vi, example_en, example_vi, audio_url, created_at, updated_at) VALUES ((SELECT id FROM topics WHERE name = 'Travel' LIMIT 1), 'destination', '/ˌdɛs.təˈneɪ.ʃən/', 'noun', 'điểm đến', 'Passengers are requested to check their luggage tags before the flight reaches its final destination.', 'Hành khách được yêu cầu kiểm tra thẻ hành lý trước khi chuyến bay đến điểm đến cuối cùng của nó.', '/uploads/audio/destination.wav', NOW(), NOW()) ON CONFLICT DO NOTHING;
INSERT INTO vocabularies (topic_id, word, phonetic, part_of_speech, meaning_vi, example_en, example_vi, audio_url, created_at, updated_at) VALUES ((SELECT id FROM topics WHERE name = 'Travel' LIMIT 1), 'reimburse', '/ˌriːɪmˈbɝːs/', 'verb', 'hoàn lại, trả lại tiền', 'The company will reimburse all travel expenses incurred during your business trip to Chicago.', 'Công ty sẽ hoàn lại tất cả các chi phí đi lại phát sinh trong chuyến công tác tới Chicago của bạn.', '/uploads/audio/reimburse.wav', NOW(), NOW()) ON CONFLICT DO NOTHING;
INSERT INTO vocabularies (topic_id, word, phonetic, part_of_speech, meaning_vi, example_en, example_vi, audio_url, created_at, updated_at) VALUES ((SELECT id FROM topics WHERE name = 'Travel' LIMIT 1), 'per diem', '/ˌpɜːr ˈdaɪ.əm/', 'noun', 'tiền công tác phí hàng ngày', 'Employees traveling for corporate business will receive a daily per diem to cover meals and lodging.', 'Nhân viên đi công tác cho việc doanh nghiệp sẽ nhận được tiền công tác phí hàng ngày để trang trải chi phí ăn ở.', '/uploads/audio/per_diem.wav', NOW(), NOW()) ON CONFLICT DO NOTHING;
INSERT INTO vocabularies (topic_id, word, phonetic, part_of_speech, meaning_vi, example_en, example_vi, audio_url, created_at, updated_at) VALUES ((SELECT id FROM topics WHERE name = 'Travel' LIMIT 1), 'expedition', '/ˌɛk.spəˈdɪʃ.ən/', 'noun', 'cuộc thám hiểm, chuyến đi', 'The corporate travel agency organized a special expedition for our team to explore the rainforest.', 'Công ty du lịch doanh nghiệp đã tổ chức một chuyến thám hiểm đặc biệt để đội ngũ chúng tôi khám phá rừng mưa.', '/uploads/audio/expedition.wav', NOW(), NOW()) ON CONFLICT DO NOTHING;
INSERT INTO vocabularies (topic_id, word, phonetic, part_of_speech, meaning_vi, example_en, example_vi, audio_url, created_at, updated_at) VALUES ((SELECT id FROM topics WHERE name = 'Travel' LIMIT 1), 'accommodation', '/əˌkɑː.məˈdeɪ.ʃən/', 'noun', 'chỗ ở', 'All travel expenses, including flights and hotel accommodation, will be fully reimbursed by the company.', 'Toàn bộ chi phí đi lại, bao gồm vé máy bay và chỗ ở khách sạn, sẽ được công ty hoàn trả đầy đủ.', '/uploads/audio/accommodation.wav', NOW(), NOW()) ON CONFLICT DO NOTHING;
INSERT INTO vocabularies (topic_id, word, phonetic, part_of_speech, meaning_vi, example_en, example_vi, audio_url, created_at, updated_at) VALUES ((SELECT id FROM topics WHERE name = 'Travel' LIMIT 1), 'confirm', '/kənˈfɝːm/', 'verb', 'xác nhận', 'Please confirm your flight reservation and hotel booking at least three days before departure.', 'Vui lòng xác nhận đặt chỗ chuyến bay và phòng khách sạn của bạn ít nhất ba ngày trước khi khởi hành.', '/uploads/audio/confirm.wav', NOW(), NOW()) ON CONFLICT DO NOTHING;
INSERT INTO vocabularies (topic_id, word, phonetic, part_of_speech, meaning_vi, example_en, example_vi, audio_url, created_at, updated_at) VALUES ((SELECT id FROM topics WHERE name = 'Travel' LIMIT 1), 'terminal', '/ˈtɝː.mɪ.نəl/', 'noun', 'nhà ga (hàng không)', 'All passengers flying to international destinations must proceed directly to terminal two for boarding.', 'Tất cả hành khách bay đến các điểm đến quốc tế phải di chuyển trực tiếp đến nhà ga số hai để lên máy bay.', '/uploads/audio/terminal.wav', NOW(), NOW()) ON CONFLICT DO NOTHING;
INSERT INTO vocabularies (topic_id, word, phonetic, part_of_speech, meaning_vi, example_en, example_vi, audio_url, created_at, updated_at) VALUES ((SELECT id FROM topics WHERE name = 'Travel' LIMIT 1), 'express', '/ɪkˈspres/', 'adjective', 'nhanh, tốc hành', 'Passengers can take the express train from the downtown station directly to the airport terminal.', 'Hành khách có thể đi tàu tốc hành từ ga trung tâm đến thẳng nhà ga sân bay.', '/uploads/audio/express.wav', NOW(), NOW()) ON CONFLICT DO NOTHING;
INSERT INTO vocabularies (topic_id, word, phonetic, part_of_speech, meaning_vi, example_en, example_vi, audio_url, created_at, updated_at) VALUES ((SELECT id FROM topics WHERE name = 'Travel' LIMIT 1), 'railway', '/ˈreɪl.weɪ/', 'noun', 'đường sắt', 'Passengers traveling to the conference can take the high-speed railway to save commuting time.', 'Hành khách đi dự hội nghị có thể đi tuyến đường sắt cao tốc để tiết kiệm thời gian đi lại.', '/uploads/audio/railway.wav', NOW(), NOW()) ON CONFLICT DO NOTHING;
INSERT INTO vocabularies (topic_id, word, phonetic, part_of_speech, meaning_vi, example_en, example_vi, audio_url, created_at, updated_at) VALUES ((SELECT id FROM topics WHERE name = 'Travel' LIMIT 1), 'round-trip', '/ˌraʊndˈtrɪp/', 'noun', 'chuyến đi khứ hồi', 'Please confirm your flight details and select a round-trip ticket for your upcoming business conference.', 'Vui lòng xác nhận chi tiết chuyến bay và chọn vé khứ hồi cho hội nghị kinh doanh sắp tới của bạn.', '/uploads/audio/round-trip.wav', NOW(), NOW()) ON CONFLICT DO NOTHING;
INSERT INTO vocabularies (topic_id, word, phonetic, part_of_speech, meaning_vi, example_en, example_vi, audio_url, created_at, updated_at) VALUES ((SELECT id FROM topics WHERE name = 'Travel' LIMIT 1), 'one-way', '/ˌwʌnˈweɪ/', 'adjective', 'một chiều', 'Passengers are advised to purchase a one-way ticket if they plan to return by bus.', 'Hành khách được khuyên nên mua vé một chiều nếu họ dự định quay lại bằng xe buýt.', '/uploads/audio/one-way.wav', NOW(), NOW()) ON CONFLICT DO NOTHING;
INSERT INTO vocabularies (topic_id, word, phonetic, part_of_speech, meaning_vi, example_en, example_vi, audio_url, created_at, updated_at) VALUES ((SELECT id FROM topics WHERE name = 'Travel' LIMIT 1), 'boarding gate', '/ˈbɔːr.dɪŋ ɡeɪt/', 'noun', 'cổng lên máy bay', 'Passengers are kindly requested to proceed immediately to boarding gate number twelve for final check-in.', 'Hành khách vui lòng di chuyển ngay đến cổng lên máy bay số mười hai để làm thủ tục cuối cùng.', '/uploads/audio/boarding_gate.wav', NOW(), NOW()) ON CONFLICT DO NOTHING;
